(window.MUSEUM_PAINT_T = window.MUSEUM_PAINT_T || {})["ru"] = {"ui":{"lead":"Люди не только играли в игры, но и рисовали их. Рассмотрите вблизи картины и фигуры за 3300 лет.","details":"Детали","links":"Посмотреть или сыграть","record":"О произведении","game":"Игра","exhibit":"Коллекция","room":"Зал","room_chance":"Случай","hint":"Масштаб — щипком или колёсиком · двигать — перетаскиванием · коснитесь номера","r_artist":"Автор","r_date":"Датировка","r_place":"Место","r_medium":"Материал и техника","r_size":"Размер","r_museum":"Музей","r_credit":"Поступление","r_rights":"Изображение","met":"Метрополитен-музей","cc0":"Открытый доступ (общественное достояние)","metlink":"Страница произведения на сайте музея","credit":"Изображения: Метрополитен-музей, Кливлендский музей искусств, Чикагский институт искусств и Рейксмузеум, открытый доступ (общественное достояние).","cma":"Кливлендский музей искусств","aic":"Чикагский институт искусств","rijks":"Рейксмузеум, Амстердам"},"nefertari":{"title":"Царица Нефертари играет в сенет","artist":"Нина де Гарис Дэвис (факсимиле)","date":"оригинал ок. 1290–1224 гг. до н. э. · факсимиле 1921–22","place":"Египет (Долина цариц)","game":"Сенет","medium":"Темпера на бумаге (факсимиле в половину натуральной величины)","p":["Нефертари была главной женой Рамсеса II. Это копия росписи из её гробницы в Долине цариц, сделанная в самой гробнице в 1921–22 годах; скопированы даже трещины и утраты стены.","Царица сидит перед доской и играет в сенет с невидимым соперником. Изображённая в гробнице, игра, вероятно, значила больше, чем развлечение: победу в пути в загробный мир."],"spots":[["Два вида фишек","На доске стоят остроконечные фишки и фишки в форме катушки — по набору у каждого игрока."],["Рука царицы","Её пальцы тянутся к фишке."],["Доска и подставка","Доска показана сбоку, поэтому клеток не видно. Она стоит на подставке с тонкими ножками."],["Её имя","Имя царицы вписано в овал — картуш."],["Невидимый соперник","Напротив никого нет: царица играет с тем, кого не видно."]]},"hydria":{"title":"Ахилл и Аякс за настольной игрой (гидрия)","artist":"Приписывается группе Леагра","date":"ок. 510 г. до н. э.","place":"Греция (Аттика)","game":"Игра в кости","medium":"Терракота (чернофигурная роспись)","p":["Во время осады Трои два греческих героя, Ахилл и Аякс, коротают время за доской. Эту сцену около 540 г. до н. э. придумал гончар и вазописец Эксекий; его оригинал сохранился на амфоре в музеях Ватикана.","Сюжет был очень любим примерно в 540–480 гг. до н. э.: известно более 150 изображений. На этой гидрии в центре стоит богиня Афина. Герои играют в игру, где фишки ходят по броску костей."],"spots":[["Афина","Богиня Афина стоит между ними."],["Герой слева","Не выпуская копья, он склонился над доской."],["Герой справа","Он тоже не отложил оружия: минута игры посреди войны."],["Доска","Низкий брусок между ними — это доска."],["Плечо сосуда","На плече гидрии отъезжает колесница."]]},"liubo":{"title":"Две сидящие фигуры, играющие в любо","date":"I в. до н. э. – I в. н. э.","place":"Китай (династия Хань)","game":"Любо","medium":"Расписная керамика","p":["Два игрока в любо — главное увлечение ханьского Китая. Такие фигуры клали в гробницы с пожеланием, чтобы радости жизни продолжались и после смерти.","На фотографии между ними лежат доска для любо и костяные фишки из коллекции этого музея. Фигуры запечатлели драматичный момент жаркой партии."],"spots":[["Доска для любо","Та же доска, что и «Доска и фишки для любо» в коллекции: видны знаки T, L и V."],["Игрок слева","Он спокойно изучает доску."],["Игрок справа","Рука поднята, рот широко раскрыт: не сделал ли он победный ход?"],["Фишки на доске","Костяные фишки стоят по обоим краям доски."],["Фишки на полу","Ещё несколько фишек лежат на полу."]]},"shahnama":{"title":"«Бузурджмихр разгадывает индийскую игру шахматы», из «Шахнаме» шаха Тахмаспа","artist":"Живопись приписывается Абд аль-Ваххабу","date":"ок. 1530–35","place":"Иран (Тебриз)","game":"Шахматы","medium":"Гуашь, тушь, серебро и золото на бумаге","p":["Сцена из поэмы Фирдоуси «Шахнаме» («Книга царей»). Царь Индии присылает посла с шахматной доской и фигурами и бросает вызов персидскому царю Ануширвану: если разгадает, как играть, Индия заплатит дань.","Разгадать вовремя сумел лишь юный мудрец Бузурджмихр. В «Шахнаме» Персия в ответ посылает нарды, и индийцы не могут их разгадать. Царь и придворные не сводят глаз с доски и игроков."],"spots":[["Шахматная доска","Фигуры стоят на клетчатой доске — такие маленькие, что их формы трудно различить."],["Царь Ануширван","На троне он ждёт разгадки."],["Вокруг доски","Игроки склонились над доской."],["Стихи","В рамках сверху и снизу — стихи Фирдоуси."],["Придворные","Люди в тюрбанах с высокими красными стержнями смотрят стоя."]]},"chaupar":{"title":"Шива и Парвати играют в чаупар, лист из серии «Расаманджари»","artist":"Девидаса из Нурпура","date":"1694–95","place":"Индия (Басохли, Джамму)","game":"Чаупар (родственник предка лудо)","medium":"Гуашь, тушь, серебро и золото на бумаге","p":["Лист из серии иллюстраций к «Расаманджари», санскритской любовной поэме XV века. Бог Шива и его супруга Парвати сидят на тигровой шкуре у крестообразной доски.","Шива только что обманом выиграл у Парвати ожерелье, и она умоляет его вернуть. Смелые краски, неопределённая глубина пространства, цвет и жест, несущие смысл, — приметы школы Басохли."],"spots":[["Крестообразная доска","В чаупар и пачиси играют на доске такой формы."],["Белые бруски на доске","Вероятно, длинные кости (паса) для чаупара."],["Шива","Белое тело, змея на шее."],["Парвати","Протянув руку, она просит вернуть ожерелье."],["Тигровая шкура","Оба сидят на тигровой шкуре."]]},"shogi":{"title":"Молодые женщина и мужчина играют в сёги («Тюнагон Канэсукэ» из серии о Тридцати шести бессмертных поэтах)","artist":"Судзуки Харунобу","date":"ок. 1767–69","place":"Япония (Эдо)","game":"Сёги","medium":"Цветная гравюра на дереве (нисикиэ)","p":["Лист из серии, обыгрывающей Тридцать шесть бессмертных поэтов; этот посвящён поэту Тюнагону Канэсукэ. Летней ночью у противомоскитной сетки молодые женщина и мужчина склонились над доской для сёги.","Харунобу — художник, сделавший популярной многоцветную гравюру, печатаемую со многих досок. Даже фигуры на доске нарисованы подробно."],"spots":[["Доска для сёги на ножках","Толстая доска на ножках, как и сегодня."],["Маленькая коробка","Вероятно, коробка для фигур."],["Противомоскитная сетка","Висит зелёная сетка — летняя ночь."],["Фонарь","Напольный светильник освещает доску."],["Стихотворение","В рамке в форме облака — имя поэта и стихотворение."]]},"sugoroku":{"title":"Две девушки играют в сугороку","artist":"Утагава Тоёкуни I","date":"период Эдо (конец XVIII – начало XIX в.)","place":"Япония (Эдо)","game":"Бан-сугороку (родственник нардов)","medium":"Диптих из цветных гравюр на дереве","p":["Две гравюры, сложенные в одну широкую картину: девушки, собравшиеся в комнате, играют в бан-сугороку. Это родственник нардов, из той же линии, что и доска для сугороку из Сёсоина в нашей коллекции.","На доске белые и чёрные шашки, а девушка справа держит стаканчик для костей. В окне виднеется Фудзи."],"spots":[["Доска","Белые и чёрные шашки на её длинных полях."],["Стаканчик для костей","В нём встряхивают кости."],["Шашки рядом с доской","Уже выведенные или ещё не введённые?"],["Фудзи","Фудзи за окном."],["Стык","Здесь сходятся две гравюры."]]},"eakins":{"title":"Шахматисты","artist":"Томас Икинс","date":"1876","place":"США (Филадельфия)","game":"Шахматы","medium":"Масло на дереве","p":["В гостиной филадельфийского дома двое друзей играют в шахматы, а отец художника, Бенджамин Икинс, наблюдает. Тщательному построению пространства и точности деталей Икинс научился у своего парижского учителя Жерома.","В 1881 году «Шахматисты» стали первым произведением, которое Метрополитен-музей принял в дар от живущего художника."],"spots":[["Фигуры","В полутёмной комнате фигуры на доске выделяются светом."],["Отец художника","Стоя, он следит за партией: Бенджамин Икинс."],["Игрок справа","Художник Джордж У. Холмс, друг отца художника."],["Ящик стола","Латинская надпись: «Сын Бенджамина Икинса написал это в 76-м»."],["Над камином","Репродукция картины Жерома, учителя Икинса."],["Кошка","На полу только кошке, кажется, нет дела до партии."]]},"weiqi":{"title":"Блюдо с бессмертными, играющими в вэйци","artist":"Неизвестный мастер","date":"1425–1436 (династия Мин, эпоха Сюаньдэ)","place":"Китай","game":"Го (вэйци)","medium":"Резной красный и зелёный лак","size":"Выс. 3,5; шир. 14,9; дл. 23,5 см","credit":"Дар Флоренс и Герберта Ирвинг, 2015","p":["Блюдо из резного лака: нанесли десятки слоёв, а затем вырезали узор; под красным слоем лежит зелёный, и глубина резьбы выявляет цвета. Внутри фигурного края бессмертные играют в го под сосной.","В Китае есть легенда о Ланькэ — «сгнившей рукояти топора»: дровосек Ван Чжи засмотрелся в горах на игру бессмертных в го, а очнувшись, понял, что прошло столько времени, что рукоять его топора сгнила. Бессмертные за доской были любимым сюжетом. Кто стоящая фигура, источники не сообщают."],"spots":[["Доска","Доска для го между двумя бессмертными, вырезанная вплоть до линий."],["Играющие бессмертные","Две фигуры сидят у скал вокруг доски."],["Стоящая фигура","Фигура стоит чуть поодаль. Она напоминает дровосека из легенды, но кто это — неизвестно."],["Луна","Круглая луна в небе (а может быть, солнце)."],["Сосна","Раскидистая сосна — дерево, часто означающее долголетие и страну бессмертных."],["Край с пионами","По краю вырезаны крупные пионы и листья."]]},"webb":{"title":"Игроки в нарды (шкаф)","artist":"Филип Уэбб (проект), Эдвард Бёрн-Джонс (живопись), «Моррис, Маршалл, Фолкнер и Ко» (изготовление)","date":"1861","place":"Великобритания (Лондон)","game":"Нарды (бэкгаммон)","medium":"Расписная сосна, масло по коже, латунь, медь","size":"Выс. 185,4; шир. 114,3; глуб. 53,3 см","credit":"Фонд Роджерса, 1926","p":["Одна из самых ранних вещей фирмы, которую Уильям Моррис основал с друзьями в 1861 году. На коже дверец маслом написаны мужчина и женщина в средневековых одеждах за игрой в нарды. Шкаф показывали на Международной выставке в Лондоне в 1862 году.","Он воплощает стремление движения «Искусства и ремёсла» стереть границу между изящными и прикладными искусствами. Фон кожи выбит мельчайшими точками — средневековый приём."],"spots":[["Доска","Доска для нард на столе между ними."],["Мужчина","Юноша с фишкой в руке смотрит на доску."],["Женщина","Напротив сидит женщина с фишкой (или стаканчиком для костей)."],["Цветы у ног","У ног игроков растут цветы."],["Выбитая кожа","Фон кожи выбит мелкими точками, которые ловят свет."],["Полосы ромбов","Полосы ромбов на золоте обрамляют дверцы сверху и снизу."]]},"liberale":{"title":"Игроки в шахматы","artist":"Либерале да Верона","date":"около 1475 г.","place":"Италия (Верона)","game":"Шахматы","medium":"Темпера на дереве","size":"34,9 × 41,3 см","credit":"Собрание Мейтланда Ф. Григгса, дар по завещанию, 1943","p":["Фрагмент передней стенки кассоне — расписного сундука, в котором в Италии эпохи Возрождения хранили приданое невесты. Либерале известен и миниатюрами в хоровых книгах Сиенского собора.","Здесь показан эпизод неизвестной любовной истории. На парном фрагменте девушка у окна будто зовёт юношу войти, а здесь они играют в шахматы. По словам музея, она вот-вот проиграет. Шахматы были любимым образом ухаживания в любовной литературе того времени."],"spots":[["Шахматная доска","Красно-белая доска с тёмными фигурами; партия, похоже, близка к концу."],["Юноша","Он тянется к доске и, кажется, вот-вот выиграет."],["Девушка","Сидит напротив; на парной доске она зовёт его из окна."],["Окно","За открытым окном — холм и небо."],["Юноши-зрители","Мужчины со скрещёнными руками следят за партией."],["Девушки-зрительницы","Девушки смотрят на игру из-за колонны."]]},"mirror":{"title":"Створка зеркала: пара играет в шахматы","artist":"Неизвестный мастер","date":"1325–1350","place":"Франция (Париж)","game":"Шахматы","medium":"Слоновая кость","size":"Диаметр 10,2 см","credit":"Приобретено на средства фонда Дж. Х. Уэйда, 1940","p":["Этот костяной диск размером с ладонь закрывал ручное зеркальце. В Париже XIV века полированное металлическое зеркало держали между двумя пластинами слоновой кости и носили с собой; такая резная кость была предметом роскоши, которую ценили при дворе и в знати.","В шатре с подвязанными занавесями юноша и дама играют в шахматы. В средневековых романах шахматы означали и любовь, и войну. В паре видели Тристана и Изольду или Ланселота и Гвиневру, но этого никто не знает. Музей спрашивает посетителей: как вы думаете, кто выигрывает?"],"spots":[["Шахматная доска","Доска на столике на одной ножке, на ней несколько фигур."],["Юноша","Он тянется к доске, чтобы сделать ход."],["Дама","Женщина в покрывале; кончики её пальцев касаются фигуры."],["Сжатая рука","Другая рука сжата и лежит на коленях. Не держит ли она взятую фигуру?"],["Шатёр","Занавеси, подвязанные с обеих сторон, — частая сцена для шахмат на створках зеркал."]]},"morris":{"title":"Игровая доска (мельница)","artist":"Петер Флётнер","date":"1500–1546","place":"Германия","game":"Мельница","medium":"Гравюра на дереве","credit":"Фонд Чарльза У. Харкнесса, 1923","p":["Гравюра на дереве Петера Флётнера, одного из самых одарённых скульпторов Нюрнберга эпохи Возрождения; он рисовал также орнаменты, мебель, модели для ювелиров и знаменитую своей сатирой колоду карт. Под вьющимися листьями прячется доска мельницы (по-немецки «Mühle»): три вложенных квадрата, соединённых посередине каждой стороны.","На доске 24 пункта. Кто выстроит три свои фишки в ряд (мельницу), снимает одну фишку соперника. Такие гравюры служили мастерам и образцами; музей показывал этот лист на выставке ювелирных моделей и эскизов. Играли ли прямо на бумаге или переносили рисунок на дерево или металл, неизвестно."],"spots":[["Центральный квадрат","Самый внутренний квадрат, заполненный тонкой плетёнкой."],["Внешний угол","Угол внешнего квадрата — один из 24 пунктов для фишек."],["Средний угол","Углы среднего квадрата — тоже пункты."],["Соединительные линии","Полосы соединяют три квадрата посередине сторон; по ним тоже ходят фишки."],["Маска","Завитые картуши с лицами сверху, снизу и по бокам — гротескный орнамент Возрождения."],["Виноградная кайма","Листья и плоды, вырезанные белым по чёрному фону."]]},"leifeng":{"title":"Настольная игра «Пагода Лэйфэн»","artist":"Неизвестный мастер","date":"1736–1795 (эпоха Цяньлун)","place":"Китай","game":"Игра-гонка","medium":"Ксилография; тушь на бумаге","size":"31 × 29,8 см","credit":"Приобретено на средства фонда Дж. Х. Уэйда, 2025","p":["Отпечатанный для игры лист времён императора Цяньлуна, Китай эпохи Цин. На его полях — герои «Легенды о Белой змее»: дух-змея Бай Сучжэнь («Белая госпожа»), её спутница Сяоцин («Зелёная»), юноша Сюй Сюань (в поздних версиях Сюй Сянь) и монах Фахай, который в конце заточает Белую госпожу под пагодой Лэйфэн у озера Сиху.","Дорожка спиралью ведёт от поля с надписью 起馬, «в путь», к пагоде в центре. Вероятно, по сюжету бежали с костями, как в западной «Игре в гусёк»; правила не сохранились. По словам музея, такие цветные листы продавались в городах и висели на стенах как часть городской визуальной культуры — каждый цвет печатали со своей резной доски."],"spots":[["Старт","Поле с надписью 起馬, «в путь», — вероятно, начало пути."],["Белая госпожа и Зелёная","Дух-змея Бай Сучжэнь и её спутница Сяоцин."],["Сюй Сюань","Юноша, который женится на Белой госпоже."],["Монах Фахай","Монах, заточающий её под пагодой."],["Пагода Лэйфэн","Пагода у озера Сиху в Ханчжоу, где кончается история."],["Центр","Женщина у пагоды и коленопреклонённый мужчина — последняя сцена истории и, возможно, финиш."]]},"tutinama":{"title":"Раненая обезьяна кусает руку принца, своего партнёра по шахматам (из «Тути-наме», «Сказок попугая»)","artist":"Дасаванта","date":"около 1560 г.","place":"Индия (двор Великого Могола Акбара)","game":"Шахматы","medium":"Гуашь, тушь и золото на бумаге","size":"20 × 14,2 см (роспись 10,2 × 10,6 см)","credit":"Дар миссис А. Дин Перри, 1962","p":["Иллюстрация к «Тути-наме», «Сказкам попугая», созданной при дворе могольского императора Акбара. Это одна из историй, которыми мать-попугаиха предостерегает птенцов от дружбы с другими видами — например, с лисятами. В ней обезьяна, искусная в шахматах, часто играла с принцем.","Однажды при гостях обезьяна грубо пошутила, принц дал ей пощёчину — и обезьяна укусила его за руку. Справа, снаружи, слуги готовят еду, а гости изумлённо смотрят. Надпись внизу называет Дасаванту, позднее одного из самых прославленных мастеров могольского двора; молодым художником он клал под живопись слой прохладного синего."],"spots":[["Обезьяна","Кусает руку принца, своего партнёра по шахматам."],["Принц","Укушенный принц."],["Шахматная доска","Доска с красными клетками на полу."],["Изумлённые гости","Гости, приглашённые на приём."],["Готовят еду","Снаружи слуги ставят котлы на огонь."],["Персидский текст","Наверху история записана по-персидски."]]},"teniers":{"title":"Игра в нарды","artist":"Давид Тенирс","date":"1640-е годы","place":"Фландрия","game":"Нарды (бэкгаммон)","medium":"Масло, дерево, переведено на холст","size":"59 × 80,6 см","credit":"Дар мистера и миссис Сэмюэл Д. Уайз, 1943","p":["Партия в нарды на большую ставку кисти фламандца Тенирса. Игра очень древняя: её современная форма появилась в XV веке, а название «бэкгаммон» возникло примерно тогда, когда была написана эта картина. В XVII веке игра была чрезвычайно популярна, и в неё часто играли на деньги.","Зеваки окружают двух игроков, а у стены кто-то ведёт счёт. По женщинам, которые смотрят на игру, — одна выглядывает из окна — музей считает эту комнату игорной в доме терпимости. Такие сцены игры часто несли мораль: азартная игра глупа, даже порочна и лишь крадёт время."],"spots":[["Доска","Раскрытая доска для нард на столе, партия идёт."],["Человек в белом","Игрок спиной к нам тянется к шашкам."],["Задумчивый","Его соперник, подперев щёку рукой."],["Счёт","Человек делает отметки на доске у стены — очки или ставки?"],["Женщина в окне","Пожилая женщина смотрит сверху."],["Задняя комната","В глубине мужчины пьют возле молодой женщины."]]},"imari":{"title":"Блюдо с двумя игроками в го","artist":"Неизвестный мастер","date":"XVIII век","place":"Япония (период Эдо)","game":"Го","medium":"Фарфор, формовка, надглазурные эмали (Хидзэн, стиль Имари)","size":"2,4 × 13,8 см","credit":"Собрание Северанса и Греты Милликин, 1964","p":["На этом маленьком квадратном блюде двое играют в го под сосной: один, в жёлтом, сидит перед доской, положенной прямо на землю, а его соперник в зелёном прислонился к дереву.","Это фарфор Имари из Хидзэна (ныне Сага и Нагасаки); его зелёные тона напоминают эмали Кутани. Блюдо сделано на экспорт, когда Япония уже сменила Китай в роли главного поставщика фарфора в Европу."],"spots":[["Доска для го","Расчерченная доска прямо на земле."],["Человек в жёлтом","Сидит перед доской."],["Человек в зелёном","Соперник, улыбаясь, прислонился к дереву."],["Сосна","Сосна раскинула ветви над игроками."],["Красная рамка","Красная рамка со срезанными углами обрамляет сцену."]]},"shoei":{"title":"Четыре искусства (одна из пары ширм)","artist":"приписывается Кано Сёэю","date":"конец XVI — начало XVII века","place":"Япония (период Момояма)","game":"Го","medium":"Одна из пары шестистворчатых ширм; тушь и лёгкие краски на бумаге","size":"153 × 358,6 см","credit":"Фонд Джона Л. Северанса, 1979","p":["Шестистворчатая ширма, приписываемая Кано Сёэю из школы Кано. Вместе с парной ширмой она изображает «четыре искусства», которыми должен был владеть образованный китайский господин: игру на цине, игру в ци (го), каллиграфию и живопись. Здесь знатные китайцы со слугами отдыхают на природе под соснами.","В центре двое играют в го, а третий наблюдает. Рядом на столе — книги и цинь, ещё в матерчатом чехле, ожидающий игры. Сцена соединяет удовольствие и благопристойность. Музей отмечает, что один из слуг отвлёкся, глядя на рыбу в воде."],"spots":[["Доска для го","Доска на ножках; двое господ играют друг против друга."],["Господа","Двое игроков и третий, который смотрит."],["Стол","Вероятно, стол с книгами и цинем в чехле."],["Слуги","Слуги ждут у стола."],["Отвлёкшийся слуга","Лёжа у воды, он смотрит на рыбу."],["Сосна","Большая сосна раскинула ветви над сценой."]]},"umaya":{"title":"Ширма с конюшней (го и сёги на веранде)","artist":"Неизвестный мастер","date":"Начало XVI века","place":"Япония (период Муромати)","game":"Го и сёги","medium":"Одна из пары шестистворчатых ширм; тушь, краски и золото на бумаге","size":"146,1 × 346,6 см","credit":"Фонд Эдварда Л. Уиттмора, 1934","p":["Эта ширма из шести соединённых створок — одна из пары. Главная тема, возможно, ценные кони в стойлах, но и на веранде перед ними много всего происходит.","Там люди состязаются в двух разных играх: слева го, справа сёги. Как пишет музей, живость сцене придаёт перекличка беспокойных коней и тихой стратегии игр. В Японии считалось, что обезьяны охраняют лошадей, и их иногда держали в конюшнях."],"spots":[["Доска го","Доска с частой разлиновкой и чёрными камнями."],["Двое в чёрных шапках","Мужчины в высоких чёрных шапках эбоси: тот, что в зелёном, тянется к доске, тот, что в красном, смотрит."],["Доска сёги","Крупные клетки — гораздо меньше, чем на доске го."],["Смеющийся соперник","Бритоголовый монах берёт фигуру, а мужчина напротив схватился за голову и хохочет. Кто-то только что выиграл очко?"],["Обезьяна","В конце веранды — обезьяна в красной куртке?"],["Конь","Чёрный конь встаёт на дыбы, удерживаемый верёвками."]]},"goryeo":{"title":"Кувшин с инкрустированными фигурами игроков в го","artist":"Неизвестный мастер","date":"XIII век","place":"Корея (династия Корё)","game":"Го (падук)","medium":"Селадон с инкрустацией белым и чёрным ангобом","size":"Выс. 20,4 см, диам. 14,3 см","credit":"Дар Джона Л. Северанса, 1917","p":["Селадоновый кувшин эпохи Корё с носиком и ручкой. Инкрустация — линии прорезают в глине, заполняют белым и чёрным ангобом, затем покрывают глазурью и обжигают — была коньком гончаров Корё; здесь в круглом медальоне белеют две фигуры, сидящие под ивой.","Между ними доска, и музей сравнивает сцену с изображениями игры в го — по-корейски падук. Игра на цитре, го, каллиграфия и живопись считались «четырьмя искусствами» образованного книжника, и их изысканные собрания стали сюжетом и для ремесленников. Корейский селадон с фигурами людей встречается редко."],"spots":[["Доска","Доска между ними — белый квадрат."],["Фигура слева","Сидит лицом к доске."],["Фигура справа","Соперник, сидящий напротив."],["Ива","Над ними свисают ветви ивы, нарисованные чёрным ангобом."],["Облачная рамка","Круглый медальон обрамляют завитки, похожие на облака."],["Кракелюр","Тонкие трещины в глазури. Они появляются при остывании, потому что глина и глазурь сжимаются по-разному."]]},"kangra":{"title":"Пара, играющая в чаупар на террасе","artist":"Неизвестный мастер","date":"Ок. 1790–1800","place":"Индия (Пахари, школа Кангры)","game":"Чаупар","medium":"Рисунок с подготовительным наброском красной охрой","size":"19,4 × 13,2 см","credit":"Фонд Эдварда Л. Уиттмора, 1936","p":["Рисунок художника из Кангры, в холмах Пахари у подножия Гималаев. Первый набросок сделан красным (красной охрой), затем уточнён чёрным. Красок поверх нет, и можно проследить каждую линию фигур и предметов.","Мужчина и женщина сидят на террасе по обе стороны крестообразной доски и играют в чаупар — старинную индийскую игру-гонку на том же кресте, что и пачиси, где ходят, бросая длинные кости (паса). Клетки на доске ещё не нарисованы. Служанки прислуживают паре."],"spots":[["Крестообразная доска","Доска в форме креста на полу. Клетки ещё не нарисованы."],["Женщина","Ладонь повёрнута вверх — сейчас бросит кости?"],["Мужчина","Тюрбан с плюмажем; он тянется к доске."],["Служанка слева","Держит маленький флакон и протягивает ткань."],["Служанка справа","Держит предмет на длинной ручке и небольшой сосуд."],["Красный набросок","Вокруг тюрбана из-под чёрных линий проступает красный набросок."]]},"vuillard":{"title":"Партия в шашки (из альбома «Пейзажи и интерьеры»)","artist":"Эдуар Вюйяр","date":"1899","place":"Франция","game":"Шашки","medium":"Цветная литография (состояние III/III); печать Огюста Кло, издатель Амбруаз Воллар","size":"Изображение 33 × 25,7 см (лист 38 × 30,8 см)","credit":"Дар фонда Ханны, 1951","p":["Амбруаз Воллар, торговец картинами импрессионистов, был и крупным издателем гравюр. В 1895 году он заказал Пьеру Боннару альбом из 12 цветных литографий, а затем выпустил ещё много альбомов, среди них «Пейзажи и интерьеры» Вюйяра, отпечатанные мастером-печатником Огюстом Кло.","Боннар и Вюйяр входили в группу «наби» («пророки» на иврите), искавшую новое искусство, где сами форма и цвет выражают чувство, и любили сцены городской и семейной жизни. В комнате, сплошь покрытой узорами, двое мужчин сидят над шашечной доской, а женщина стоя следит за игрой. По-французски шашки — «dames»; карандашная надпись внизу слева читается как «partie de dames», партия в шашки."],"spots":[["Доска","Маленькая клетчатая доска с расставленными шашками."],["Мужчина слева","Бородатый мужчина протягивает руку над доской."],["Мужчина справа","Его соперник склонился над доской в кресле; его наполовину заслоняет стоящая женщина."],["Стоящая женщина","Подперев подбородок рукой, она следит за партией."],["Лампа","Лампа у стены. Обои и обивка полны узоров."],["Карандашная надпись","Внизу слева карандашом: «partie de dames» — партия в шашки."]]},"talbot":{"title":"Шахматисты (ранняя фотография)","artist":"Приписывается Уильяму Генри Фоксу Тальботу","date":"Ок. 1843–47","place":"Англия","game":"Шахматы","medium":"Отпечаток на солёной бумаге","size":"19,9 × 15 см","credit":"Приобретено на средства г-на и г-жи Эверетт Ковлер","p":["Изобретённый Тальботом негативно-позитивный процесс, позволявший печатать сколько угодно копий, господствовал в фотографии до цифровой эпохи. Его ранние опыты показывают и интерес к науке, и художественные устремления; исследователи подтвердили, что он сделал не менее десяти снимков шахматистов.","Но этот, возможно, не его: этот и другие отпечатки сцены не подписаны и сделаны на другой бумаге, чем обычно у Тальбота. Изображены, вероятно, фотограф Антуан Клоде и ассистент Тальбота Николас Хеннеман; по новым данным, снимки сделаны в мастерской Клоде, перешли к Хеннеману и попали к Тальботу, когда тот отдал их в счёт долга (пояснение музея)."],"spots":[["Доска","Шахматная доска на столе, фигуры выстроены в ряд."],["Мужчина в цилиндре","Не снимая шляпы, он берётся за фигуру."],["Задумавшийся","Подперев подбородок, соперник изучает доску."],["Занавес","Позади висит занавес — фон для съёмки?"],["Ещё одна шляпа","Второй цилиндр лежит на подставке справа."]]},"pvl":{"title":"Мужчины, играющие в кости","artist":"Мастер PVL","date":"Ок. 1520","place":"Нидерланды","game":"Кости","medium":"Резцовая гравюра на бумаге","size":"9,4 × 9,4 см (круглая)","credit":"Собрание Чарльза Хака и семейного фонда Хирн, приобретено в 2023","p":["Работа безымянного гравёра, работавшего в Нидерландах в начале XVI века; по монограмме «PVL» внизу слева его называют Мастером PVL. На круглом листе, умещающемся на ладони, частые тонкие линии передают глубину комнаты и фактуру одежды.","На столе две кости. Наклонившийся мужчина и юноша с меховым воротником показывают пальцами и спорят — может быть, о счёте. Сзади смотрят женщины, под столом стоит кувшин вина. Кости с древности связаны с азартной игрой и не раз запрещались."],"spots":[["Кости","Две кости катятся по столу."],["Указующие руки","Два пальца встречаются на столе — спор о счёте?"],["Мужчина в широкой шляпе","Наклонился вперёд; его разрезные пышные рукава были модой того времени."],["Юноша с меховым воротником","Большая шляпа и меховой воротник."],["Женщины-зрительницы","Женщины заглядывают в игру сзади."],["Монограмма","«PVL» внизу слева — единственная подсказка к имени художника."]]},"kiyohiro":{"title":"Игроки в сугороку","artist":"Тории Киёхиро","date":"Ок. 1750","place":"Япония (период Эдо)","game":"Бан-сугороку","medium":"Цветная ксилография (бэнидзури-э), формат обан; издатель Урокогатая","size":"43,5 × 29,3 см","credit":"Собрание Кларенса Бакингема","p":["Тории Киёхиро — художник укиё-э, работавший примерно с 1737 по 1776 год. Это бэнидзури-э, напечатанная немногими цветными досками — розовой бэни, зелёной и подобными — в годы до появления в 1765 году многоцветных нисики-э.","На чёрной подставке — доска бан-сугороку: двое бросают кости и двигают белые и чёрные шашки, и побеждает тот, кто первым выведет все свои. Это игра того же семейства, что и нарды, и на гравюрах укиё-э часто изображали женщин за ней. Позади женщина курит длинную трубку и смотрит."],"spots":[["Доска","Доска сугороку на подставке, с белыми и чёрными шашками."],["Фигура слева","Тянется, чтобы передвинуть шашку."],["Женщина справа","Склонившись над доской, соперница изучает шашки."],["Женщина с трубкой","С длинной трубкой кисэру следит за игрой сзади."],["Поднятая рука","Женщина справа поднимает что-то маленькое и чёрное — стаканчик для костей?"],["Подпись","«Тории Киёхиро хицу» и печать издателя Урокогатая."]]},"ingram":{"title":"Игра в китайские шахматы","artist":"Джон Ингрэм, по рисунку Франсуа Буше","date":"1741–63","place":"Франция (Париж)","game":"Сянци","medium":"Офорт и резцовая гравюра","size":"Лист 39,4 × 27,7 см (доска 24,5 × 16,4 см)","credit":"Собрание Элиши Уиттлси, 1966","p":["Рисунок французского живописца Франсуа Буше, гравированный уроженцем Лондона Джоном Ингрэмом. Ингрэм переехал в Париж и в 1741–1763 годах выпустил серию гравюр по шинуазри Буше — Китаю, каким его представляли европейцы. Надпись внизу: «LE JEU D'ECHETS CHINOIS», игра в китайские шахматы.","Женщина с высокой причёской передвигает фигуру на доске у себя на коленях, рядом смотрит маленький ребёнок. Игру принято считать сянци, но настоящие фигуры сянци — плоские диски, а здесь высокие фигуры стоят рядом с маленькими квадратными. Пальма и фигурка на урне тоже принадлежат не столько Китаю, сколько далёкой стране, о которой грезила тогдашняя Европа."],"spots":[["Доска и фигуры","Доска на коленях, с высокими и квадратными фигурами. Настоящие фигуры сянци — плоские диски."],["Рука у фигуры","Её правая рука передвигает фигуру."],["Щека на руке","Подперев подбородок левой рукой, она смотрит на доску."],["Смотрящий ребёнок","Ребёнок стоит у доски и следит за игрой."],["Фигурка на урне","Фигурка сидит, скрестив ноги, на большой урне."],["Название и имена","«Dessiné par Fr. Boucher», «Gravé par Ingram» и название «LE JEU D'ECHETS CHINOIS»."]]},"posada":{"title":"Игра в гусёк","artist":"Хосе Гуадалупе Посада","date":"1909","place":"Мексика","game":"Игра в гусёк","medium":"Высокая печать с цинковой доски на бумаге","size":"29,3 × 39,4 см","credit":"Мемориальный фонд Уильяма Маккаллина Макки","p":["Лист для игры, созданный мексиканским графиком Посадой — знаменитым своими скелетами-калаверами — для издателя из Мехико Антонио Ванегаса Арройо. На ленте внизу слева написано «JUEGO DE LA OCA» (игра в гусёк), а дорожка спиралью идёт от клетки 1 к 63 в центре.","В центре напечатаны правила (EXPLICACION): если первым броском выпали 5 и 4 — идти на 26, если 6 и 3 — на 53. Попавший на гуся (птицу) отсчитывает столько же ещё раз; на постоялом дворе (Venta, 19) пропускают два хода; в колодце (Poso, 31) и тюрьме (Carcel, 52) остаются, пока не придёт другой; лабиринт (42) отправляет назад на 39, смерть (Muerte, 58) — в начало. На 63 нужно попасть точно. На некоторых клетках платили ставку: это была и азартная игра."],"spots":[["Правила","«EXPLICACION» в центре: что делает каждая клетка и когда платить ставку."],["Клетка 1","Старт. Отсюда дорожка спиралью идёт к центру."],["Колодец (31)","Колодец, похожий на фонтан. Попавший остаётся, пока не придёт другой."],["Смерть (58)","Клетка с черепом: назад к началу."],["Лента с названием","«JUEGO DE LA OCA» на ленте внизу слева, под ней играют дети."],["Имя издателя","На ленте богини — «IMPRENTA DE A. VANEGAS ARROYO», издательство многих гравюр Посады."]]},"jintile":{"title":"Плитка с женщинами за настольной игрой","artist":"Неизвестный мастер","date":"XIII век","place":"Китай (династия Цзинь)","game":"Настольная игра (вероятно, го)","medium":"Керамика (формованный рельеф)","size":"Выс. 27,3 см, шир. 24,8 см, толщ. 5,4 см","credit":"Приобретено на пожертвования Friends of Asian Art, 2002","p":["Рельефная плитка эпохи Цзинь (1115–1234) — династии чжурчжэней, правивших Северным Китаем. Под цветущим деревом на помосте друг против друга сидят две женщины, между ними доска.","На доске частая сетка, так что они, вероятно, играют в го. Женщина справа наклонилась и указывает на доску, женщина слева смотрит. Многие гробницы эпохи Цзинь в Северном Китае облицовывали кирпичами с рельефами повседневной жизни, и эта плитка, вероятно, украшала такую гробницу."],"spots":[["Доска","Доска с частой сеткой — вероятно, для го."],["Указующая рука","Женщина справа указывает на доску. Её следующий ход?"],["Женщина слева","С высокой причёской, она смотрит на доску."],["Женщина справа","Склонилась над доской."],["Цветущее дерево","Над ними раскинулись ветви цветущего дерева."],["Помост","Помост, на котором они сидят, с фестончатым подзором между ножками."]]},"kyosai":{"title":"Пук опрокидывает партию в го (из альбома набросков)","artist":"Каванабэ Кёсай","date":"Середина — конец XIX века","place":"Япония (периоды Эдо — Мэйдзи)","game":"Го","medium":"Разворот альбома-гармошки из 26 двойных листов; тушь и краски на бумаге","size":"Альбом (в сложенном виде) 28 × 18 см","credit":"Дар Энн и Энтони д’Оффэй в честь Эвана Тёрнера","p":["Сцена из альбома набросков Каванабэ Кёсая (1831–1889) — художника, работавшего с конца сёгуната до эпохи Мэйдзи, — быстрыми свободными мазками на страницах складного альбома. Выученик строгой школы Кано, Кёсай был любим и за демонов, карикатуры и сатиру.","Название музея говорит само за себя: «Пук опрокидывает партию в го». Слева мужчина в чёрной шапке нагнулся; справа доска летит по воздуху, из чаш дождём сыплются камни, а соперник падает навзничь. Серьёзная партия погублена одним залпом: Кёсай быстрой кистью продолжает старую японскую традицию юмора о пуках, известную ещё по средневековым свиткам."],"spots":[["Мужчина в чёрной шапке","Нагнулся, выставив зад, — виновник переполоха?"],["Летящая доска","Расчерченная доска го улетает наискось."],["Чаши и камни","Две чаши опрокидываются, и камни сыплются вниз."],["Веер","Раскрытый веер тоже уносит рядом с доской."],["Опрокинутый соперник","Лежит на спине, широко раскрыв глаза."],["Линия кисти","Энергичные линии туши, словно проведённые разом, без наброска."]]},"yokuts":{"title":"Поднос для азартной игры","artist":"Мастерица народа йокутс (имя неизвестно)","date":"Ок. 1900","place":"США (близ Данлапа, Калифорния)","game":"Хучуиш (кости из скорлупы ореха)","medium":"Растительные волокна (спиральное плетение)","size":"Выс. 5,1 см, диам. 61 см","credit":"Приобретено на средства миссис Леонард С. Флоршайм-младшей","p":["Многие коренные народы Калифорнии играли в азартные игры. Этот поднос служил для хучуиш — игры в кости, в которую играли только женщины: на поднос бросали восемь костей из скорлупы грецкого ореха, а очки считали палочками.","Круговой узор, вплетённый в поднос, изображает саму игру — кости, счётные палочки и игроков (пояснение музея). Это игровой предмет, несущий изображение собственной игры. На фотографии кости из скорлупы лежат на подносе и вокруг него."],"spots":[["Игроки","Фигуры идут по кругу у края — участницы игры."],["Счётные палочки","Пучки коротких вертикальных черт — палочки для счёта."],["Круглые мотивы","Маленькие круглые мотивы — может быть, кости?"],["Ореховая кость","Кость из скорлупы ореха. На поднос бросали восемь."],["Пояс треугольников","Полоса тёмных треугольников идёт по кругу."],["Центр","Плетение спиралью выходит из центра, окружённое пунктирным кольцом."]]},"hokkei":{"title":"Усивакамару обыгрывает Бэнкэя в сугороку","artist":"Тотоя Хоккэй","date":"Ок. 1825","place":"Япония (период Эдо)","game":"Бан-сугороку","medium":"Суримоно (цветная ксилография, сикисибан)","size":"21,8 × 19,1 см","credit":"Дар Хелен К. Гансолус","p":["Суримоно Тотоя Хоккэя (1780–1850), ученика Хокусая. Суримоно заказывали частным образом — часто поэтические кружки, со своими стихами, — и печатали роскошнее, чем коммерческие укиё-э: на хорошей бумаге, с металлическими пигментами.","Усивакамару — детское имя героя Минамото-но Ёсицунэ — и великан-монах Бэнкэй. Их знаменитая встреча — поединок на мосту Годзё в Киото, но здесь схватка превращается в партию сугороку: мальчик спокойно сидит за доской, а Бэнкэй с алебардой за спиной чешет затылок, признавая поражение. Похоже, это шутливое переосмысление."],"spots":[["Доска сугороку","Доска-ящик с белыми и чёрными шашками."],["Бэнкэй чешет затылок","В полном доспехе побеждённый чешет затылок."],["Усивакамару","Юный герой сидит за доской."],["Алебарда","Лезвие большой нагинаты Бэнкэя."],["Стихи","Стихи вверху справа — вероятно, кружка, заказавшего гравюру."],["Подпись","Подпись Хоккэя в картуше внизу справа."]]},"vorsterman":{"title":"Игроки в нарды (ночная сцена)","artist":"Лукас Эмиль Ворстерман, по картине Адама де Костера","date":"Ок. 1630","place":"Фландрия (Антверпен)","game":"Нарды (бэкгаммон)","medium":"Резцовая гравюра на бумаге цвета слоновой кости","size":"Изображение 25,5 × 34,4 см","credit":"Собрание Бернарда Ф. Роджерса","p":["Адам де Костер около 1630 года был в Антверпене известным мастером ночных сцен при свечах; тогда же Ворстерман в том же городе гравировал работы популярных современников. Ученик Рубенса, он поссорился с учителем и уехал в Англию, после чего стал делать более контрастные, стилизованные, караваджистские гравюры, как эта.","За столом в тёмной комнате мужчины собрались над доской для нард. Вслед за де Костером два огонька свечей освещают лица вокруг стола (пояснение музея). Справа юноша с лютней смотрит на нас."],"spots":[["Доска","Доска для нард, раскрытая как ящик, на столе."],["Свеча","Свеча в подсвечнике; её пламя освещает лица."],["Мужчина с трубкой","В широкой шляпе, курит и следит за игрой."],["Мужчина со спины","Наклонился, опираясь руками о стол."],["Юноша с лютней","Юноша с лютней улыбается нам."],["Имена","«A. De Coster pi.» внизу слева, «Vorsterman» внизу справа."]]},"zorn":{"title":"Шахматисты","artist":"Андерс Цорн","date":"1891","place":"Швеция","game":"Шахматы","medium":"Офорт на бумаге верже цвета слоновой кости","size":"Изображение 13,5 × 9,6 см (доска 13,9 × 10 см)","credit":"Собрания офортов Андерса Цорна Уоллеса Л. Девулфа и Чарльза Диринга","p":["Офорт шведского художника Андерса Цорна (1860–1920), прославившегося портретами маслом и акварелью и оставившего также большое наследие в гравюре. Доска не больше ладони.","Довольно быстрых наклонных линий, положенных одна на другую, чтобы из меди возникли тёмная комната и двое людей. Мужчина на переднем плане, спиной к нам, склонился над доской; фигура напротив опустила взгляд, обдумывая ход. Фигуры на доске нарисованы тонкими штрихами. Кто позировал — неизвестно."],"spots":[["Доска и фигуры","Светлая часть внизу — доска; короткие вертикальные штрихи — фигуры."],["Мужчина спереди","Спиной к нам, склонился над доской."],["Соперник","Опустив голову, смотрит на доску."],["Тёмный фон","Глубина комнаты из вертикальных линий."],["Наклонные линии","Сюртук из быстрых наложенных диагональных штрихов."],["Подпись","Под доской карандашом подпись «Zorn»."]]},"harunobu-sugoroku":{"title":"Наблюдая за игрой (сугороку)","artist":"Судзуки Харунобу","date":"Ок. 1766","place":"Япония (период Эдо)","game":"Бан-сугороку","medium":"Цветная ксилография (тюбан, суримоно)","size":"28,5 × 21 см","credit":"Собрание Кларенса Бакингема","p":["Судзуки Харунобу (1725?–1770) был центральной фигурой, когда около 1765 года появились нисики-э — полноцветные гравюры, печатавшиеся со многих досок. Это частное суримоно, и мягкие наложенные цвета показывают новизну.","В комнате с цветущей сливой две девушки играют на доске сугороку в виде ящика, а третья стоя смотрит на игру. На доске белые и чёрные шашки; девушка слева передвигает шашку, девушка справа тянется к доске. На раздвижной двери позади нарисованы водопад и сосны."],"spots":[["Доска сугороку","Доска бан-сугороку в виде ящика, с белыми и чёрными шашками."],["Девушка слева","В кимоно с бумажными журавликами, передвигает шашку."],["Девушка справа","Наклонившись, тянется к доске."],["Зрительница","Стоя смотрит на игру, держа предмет на длинной ручке."],["Слива","Белая слива тянет ветви сверху."],["Расписная дверь","Раздвижная дверь с водопадом и соснами."]]},"kota":{"title":"Махарао Кишор Сингх II из Коты поклоняется Кришне в образе Брадж Раджи","artist":"Неизвестный мастер","date":"Ок. 1825","place":"Индия (Раджастхан, Кота)","game":"Пачиси","medium":"Темпера на гумми, серебро и золото на бумаге","size":"24,5 × 18,8 см","credit":"Мемориальный фонд Джеймса Альберта и Мэри Гардинер Форд","p":["Правитель маленького княжества Кота (правил 1819–28), одетый жрецом секты Пуштимарг, подносит светильник с пятью огнями. В маленьком святилище на алтаре стоят металлические изображения Кришны с двумя супругами — икона, почитаемая только в Коте.","С потолка свисает множество стеклянных ламп, а на ступенях к алтарю разложены игрушки и игры для развлечения Кришны и его спутников: латунные слоны, серебряные коровы, мячи и доска для пачиси (пояснение музея). Красная крестообразная ткань — это и есть доска: пачиси, поднесённое богу как игрушка."],"spots":[["Доска пачиси","Красная крестообразная ткань на ступенях — доска для пачиси."],["Слоны","Два латунных слона рядом с доской."],["Мячи","Золотые мячи на ступени выше."],["Кришна","Изображения Кришны и двух супруг в святилище."],["Правитель и светильник","В облике жреца он подносит светильник с пятью огнями."],["Стеклянные лампы","С потолка свисает множество стеклянных ламп."]]},"coyote":{"title":"Игра в койота","artist":"Последователь Хосе Гуадалупе Посады","date":"Без даты","place":"Мексика","game":"Койот и куры (из семейства «лиса и гуси»)","medium":"Высокая печать с цинковой доски на бумаге","size":"38,2 × 30,5 см","credit":"Мемориальный фонд Уильяма Маккаллина Макки","p":["Лист для игры, отпечатанный с цинкового рельефа — так же, как листы, которые Посада делал для народных типографий Мехико. Вверху написано «JUEGO DEL COYOTE» (игра в койота); вокруг койоты нападают на курятник, а человек замахивается палкой, прогоняя одного. На полосе внизу: «Собственность Ильдефонсо Т. Орельяны».","Правила напечатаны в «EXPLICACION» внизу: играют двое, у одного пятнадцать кур, у другого один койот. Куры ходят вперёд и в стороны, но никогда назад; койот ходит во все стороны и съедает курицу, перепрыгивая через неё, если за ней пусто. Куры побеждают, заперев койота. Это та же охотничья игра, что и европейская «лиса и гуси»."],"spots":[["Место койота","Голова койота в центральном круге: отсюда начинает койот."],["Места кур","Круги с курами: сюда ставят их фишки."],["Правила","«EXPLICACION»: фишки, ходы и условия победы."],["Название","«JUEGO DEL COYOTE» — игра в койота."],["Койот за курицей","Внизу слева койот бросается на курицу."],["Человек с палкой","Вверху справа человек поднимает палку на койота."]]},"mons":{"title":"Игра в триктрак на Монс (Берген), 1709","artist":"Питер Нолпе (доска и издатель)","date":"Доска 1623–53; отпечаток ок. 1709","place":"Нидерланды (Амстердам)","game":"Триктрак (из семейства нард)","medium":"Офорт, резцовая гравюра и наборный стих","size":"Лист 35,8 × 18,6 см (доска 12,9 × 17,5 см)","credit":"","p":["Четверо мужчин играют за столом в триктрак. По записи музея, буквы A–D обозначают герцога Мальборо, курфюрста Баварского, господина Оуверкерка и герцога Виллеруа. Это сатира на осаду и взятие союзниками у французов Монса (по-нидерландски Берген) в 1709 году, показанные как партия, где ставка — город. В задней комнате (E) испанский король Филипп V с женщиной.","Доска подписана Питером Нолпе как гравёром и издателем, но Нолпе умер в начале 1650-х, — вероятно, старую доску XVII века перепечатали, добавив буквы и новые стихи. Стихи начинаются словами о том, что игра знатных господ — сплошь тиктак и веркеер (две игры этого семейства), а затем высмеивают каждого игрока."],"spots":[["Доска","Триктрак на столе: на кону город."],["A, Мальборо","Стоя смотрит на доску — английский полководец союзников."],["B, курфюрст Баварский","Без шляпы, развалился на стуле."],["C, Оуверкерк","В шляпе с плюмажем — нидерландский генерал."],["E, задняя комната","В глубине, в спальне, Филипп V с женщиной."],["Стихи","Нидерландские стихи внизу высмеивают игроков от A до E."]]},"stembus":{"title":"Урна: политическая игра в гусёк","artist":"Йохан Михаэль Шмидт Кранс (гравёр)","date":"1867","place":"Нидерланды","game":"Игра в гусёк (сатира)","medium":"Литография","size":"66 × 50 см","credit":"","p":["Сатирический лист в форме игры в гусёк. Он вышел приложением к еженедельнику De Nederlandsche Spectator, № 9, 2 марта 1867 года, вместе с отдельным листком правил (запись музея). В клетках — портреты тогдашних министров.","Игра начинается у Бинненхофа — парламента в Гааге — и заканчивается в центре, на клетке 64 «Инсулинде» (поэтическое название Нидерландской Ост-Индии), где к острову Ява подвешен портрет министра Питера Мейера. Мейер из министра колоний стал генерал-губернатором Индии, и это назначение вызвало политическую бурю. Лишняя клетка — на одну больше обычных 63, — вероятно, нужна ради концовки."],"spots":[["Старт","Здание вверху слева: игра начинается у Бинненхофа в Гааге."],["Портрет Мейера","Клетка 63: портрет Питера Мейера в раме, подвешенный на верёвках к острову."],["Инсулинде 64","Остров и число 64 в центре — финиш."],["Урна","«DE STEMBUS» (урна) внизу справа — ящик из названия."],["Министры","Из клеток выглядывают лица тогдашних министров."],["Петух","Петух в одной из клеток; над чем он смеётся, неизвестно."]]},"koorai":{"title":"Корейцы за настольной игрой (из «Ниппона» Зибольда)","artist":"Джеймс Эрксклебен (литограф), по рисунку «Тойоскэ»","date":"1832–52","place":"Нидерланды (Лейден) / жители Кореи","game":"Настольная игра (вероятно, го)","medium":"Тоновая литография, раскрашенная от руки","size":"Лист 38 × 55,5 см","credit":"Дар Ф. Г. Валлера","p":["Таблица из NIPPON — большого труда, который уроженец Германии врач Филипп Франц фон Зибольд издал в Лейдене по впечатлениям от жизни в нидерландской фактории в Нагасаки (1823–30). Вверху справа «TAB. I», внизу «KOORAI» (Корея) и по-нидерландски и по-немецки «семья рыбака». На камне рисовал Эрксклебен; автором рисунка лист называет «Тойоскэ».","Четверо мужчин сидят на земле вокруг доски; слева женщина ведёт за руку маленького ребёнка, справа стоит мужчина с длинной палкой и кисетом. Впереди на земле — чёрная широкополая шляпа (кат). На доске видны сетка и круглые камни, так что это, вероятно, го (по-корейски падук), хотя в записи сказано лишь «настольная игра»."],"spots":[["Доска","Сетка с круглыми камнями — вероятно, партия в го."],["Чёрная шляпа","Широкополая чёрная шляпа (кат) на земле."],["Мать и дитя","Женщина с ребёнком за руку смотрит на игру."],["Стоящий мужчина","Стоит с длинной палкой и кисетом."],["Склонившийся мужчина","В синей куртке, вглядывается в доску."],["Название","«KOORAI» (Корея) и по-нидерландски и по-немецки «семья рыбака»."]]},"cairo":{"title":"Люди за настольной игрой у кафе (Каир)","artist":"Делье и Бешар (Ипполит Делье и Эмиль Бешар)","date":"Ок. 1869–90","place":"Египет (Каир)","game":"Настольная игра (вероятно, шахматы)","medium":"Альбуминовый отпечаток","size":"10,8 × 16,4 см","credit":"","p":["Фотография Ипполита Делье и Эмиля Бешара — французских фотографов с ателье в Каире. На паспарту напечатаны название ателье «У сада Эзбекия» и «Каир (Египет)». Такие снимки покупали на память путешественники.","Мужчины сидят на земле перед лавкой с решётчатым окном вокруг доски на низкой подставке. На доске стоят высокие фигуры — вероятно, шахматы (по-арабски шатрандж), хотя в записи музея сказано лишь «настольная игра». Ради долгой выдержки все сидят неподвижно."],"spots":[["Доска и фигуры","Доска на низкой подставке с высокими фигурами — вероятно, шахматы."],["Решётчатое окно","Окно с деревянной решёткой, типичное для старых каирских домов."],["Мужчина с палкой","Сидит с палкой и следит за игрой."],["Корзина","Плетёная корзина на земле."],["Смотрящий ребёнок","Ребёнок заглядывает на доску сзади."],["Название ателье","«AU JARDIN DE L’ESBÉKIEH» и «CAIRE (EGYPTE)» на паспарту."]]},"vanmour":{"title":"Армяне за карточной игрой","artist":"Жан-Батист Ванмур","date":"Ок. 1720–37","place":"Османская империя (Стамбул)","game":"Карты","medium":"Холст, масло","size":"44,5 × 58,5 см","credit":"","p":["Уроженец Фландрии Ванмур приехал в Стамбул в 1699 году с французским послом и прожил в городе до самой смерти, изображая придворные церемонии и повседневную жизнь горожан. Музей отмечает, что по одежде мужчин видно: это армяне.","При свете большой свечи мужчины и женщины играют в карты за столом, покрытым красной скатертью. На столе лежат розданные карты, кто-то разглядывает свои. В левом углу старуха прядёт. Какая это игра, в записи не сказано."],"spots":[["Карты на столе","Карты на столе под красной скатертью."],["Большая свеча","Одна свеча освещает всю компанию."],["Прядущая старуха","Старуха прядёт в левом углу."],["Женщина с картами","Справа женщина рассматривает свои карты."],["Мужчина в мехах","Мужчина в кафтане с меховой опушкой; по одежде видно, что это армяне."],["Склонившийся над столом","Кто-то склонился над столом с картами в руке."]]},"algiers":{"title":"Трое мужчин за настольной игрой (Алжир)","artist":"Неизвестный автор","date":"1851–1900","place":"Алжир (город Алжир)","game":"Настольная игра (вероятно, нарды)","medium":"Альбуминовый отпечаток","size":"14,0 × 10,0 см","credit":"","p":["Фотография неизвестного автора с надписью от руки «Alger» (Алжир) под изображением. Стулья и столик перед гладким фоном говорят о том, что снимали, вероятно, в ателье. Такие снимки жителей Северной Африки покупали путешественники и коллекционеры.","Двое мужчин сидят друг против друга у доски с бортиком; правый тянется к шашке. На доске стопками лежат круглые шашки — вероятно, нарды (в тех краях их зовут таула и другими именами), хотя в записи сказано лишь «настольная игра». На столике впереди — кофейная посуда."],"spots":[["Доска и шашки","Доска с бортиком, на ней стопки круглых шашек."],["Стоящий зритель","Мужчина с кушаком стоит позади и смотрит на игру."],["Старик слева","Пожилой мужчина в повязанном платке, в раздумье."],["Мужчина справа","С белым покрывалом на голове склонился над доской."],["Кофейная посуда","Поднос и чашечки на резном столике."],["Рука, делающая ход","Рука правого игрока вот-вот возьмёт шашку."]]},"circo":{"title":"Цирковая игра (Juego del Circo)","artist":"Мануэль Манилья (?)","date":"Без даты","place":"Мексика","game":"Азартная игра на двух костях","medium":"Высокая печать (торцовая гравюра или фотоцинкография) на светло-коричневой веленевой бумаге","size":"26,2 × 35,0 см","credit":"","p":["Игровой лист, который с вопросительным знаком приписывают мексиканскому графику Мануэлю Манилье. Внизу справа указан продавец — печатня «Эль Театро» — с адресом. Такие дешёвые листы продавали на улице и, видимо, играли прямо на них.","В центре — цирковой шатёр, вокруг — наездники-акробаты, живая башня, силач и другие, у каждой картинки число от 2 до 12. «Объяснение» слева вверху говорит: играть могут все, и дети тоже; бросают две кости и ставят на выпавшее поле или забирают то, что там уже лежит. Кто выбросит двенадцать, берёт всё."],"spots":[["Цирковой шатёр","Заголовок «JUEGO DEL CIRCO» и шатёр — поле 12."],["Правила","Правила под заголовком «ESPLICACION»."],["Наездница","Танцовщица на скачущей лошади — поле 6."],["Живая башня","Человек стоит на плечах другого — поле 4."],["Силач","Мужчина поднимает гирю в виде пушки — поле 8."],["Название печатни","«De venta, Estampería “El Teatro”» и адрес."]]},"loteria":{"title":"Лотерия: лист с картинками","artist":"Хосе Гуадалупе Посада","date":"1880–1913","place":"Мексика","game":"Лотерия (игра с выкликанием картинок)","medium":"Высокая печать (торцовая гравюра или фотоцинкография) на светло-коричневой веленевой бумаге","size":"30,0 × 40,0 см","credit":"","p":["Мексиканский график Посада нарисовал множество картинок для издателя Антонио Ванегаса Арройо из Мехико, чьи дешёвые листы несли новости, песни и игры. На этом листе — заголовок «JUEGO DE LOTERIA» и имя Ванегаса Арройо.","Лист заполняют тридцать восемь подписанных картинок: звезда, луна, скорпион, чёрт, череп, петух, типография и другие. В лотерии, похожей на бинго, ведущий тянет карты и называет картинки, а игроки отмечают их на своих таблицах фасолинами и т. п. Лист, вероятно, разрезали на карты."],"spots":[["Заголовок и издатель","«JUEGO DE LOTERIA» и название дома Ванегаса Арройо."],["Звезда","«ESTRELLA», первая картинка слева вверху."],["Луна","«LUNA», месяц с лицом."],["Смерть","«MUERTE»: скелет с косой играет на дудке."],["Тлачикеро","«TLACHIQUERO»: человек, собирающий сок агавы."],["Типография","«IMPRENTA»: рабочие у пресса — здесь и печатали такие листы."]]},"jeupol":{"title":"«Польская игра», или доска для шашек","artist":"Неизвестный автор","date":"1833–1900","place":"Бельгия или Нидерланды","game":"Шашки (доска 10 × 10)","medium":"Ксилография с наборным текстом","size":"32,2 × 39,6 см","credit":"","p":["Отдельный лист с французско-нидерландским заголовком «JEU POLONAIS OF DAMSPEL». «Польской игрой» во Франции называли шашки на доске 10 × 10. Вверху справа — издательский номер «n. 106».","Как сказано в записи музея, здесь 100 полей, 50 белых и 50 чёрных, а слева и справа — орнаментальные каймы. Шашек не напечатано: вероятно, это дешёвая доска, на которой играли прямо так, фасолинами или пуговицами. На бумаге видны сгибы."],"spots":[["Заголовок","Слова «JEU POLONAIS OF DAMSPEL»."],["Номер","Издательский номер «n. 106»."],["Левая кайма","Столбец круглых розеток."],["Правая кайма","Тот же узор с другой стороны."],["Сто полей","Доска 10 × 10; тёмные поля заштрихованы."],["Сгиб","Сгиб на бумаге; возможно, лист носили сложенным."]]},"dkaart":{"title":"Домино и карты для вырезания","artist":"Неизвестный автор (издание Брепольса)","date":"1800–1833","place":"Бельгия (Тюрнхаут)","game":"Домино и карты","medium":"Ксилография, раскрашенная синим, красным и жёлтым; наборный текст","size":"34,3 × 41,9 см","credit":"","p":["По записи музея, на листе напечатаны 32 игральные карты и 28 костей домино для вырезания. Это номер 114 в каталоге издателя Брепольса, внизу — продавец «Д. Поувелс, Берген-оп-Зом». Заголовок дан по-нидерландски и по-французски.","Слева 28 костей, от пусто-пусто до шесть-шесть, сложены треугольником. Справа — 32 карты, от семёрки до десятки, фигуры и тузы каждой масти: колода для пикета и подобных игр. Лист никто не разрезал, и мы видим его таким, каким он вышел из-под пресса."],"spots":[["Заголовок","Слова «DOMINO EN KAARTSPEL»."],["Пусто-пусто","Вершина треугольника: кость без очков."],["Шесть-шесть","Старшая кость, справа в нижнем ряду."],["Туз пик","Вторая карта в левом столбце."],["Фигура","Король, раскрашенный красным, синим и жёлтым."],["Продавец","«D. POUWELS, Bergen-op-Zoom» внизу."]]},"apen":{"title":"Две обезьяны играют в триктрак","artist":"Квирин Бул по рисунку Давида Тенирса","date":"1635–1690","place":"Фландрия","game":"Триктрак (родственник нард)","medium":"Офорт","size":"11,0 × 14,5 см","credit":"","p":["Лист из серии — титул и шесть листов, — где обезьяны изображают человеческие занятия. Внизу слева: «Д. Тенирс сочинил и издал, с привилегией» — Квирин Бул выгравировал композицию фламандского художника Тенирса.","Как сказано в записи музея, две обезьяны сидят на полу, между ними доска для триктрака. Левая пьёт вино из бокала, правая в шляпе с петушиным пером тянется к шашке. Вероятно, это насмешка над людьми, предавшимися вину и игре."],"spots":[["Доска","Складная доска для триктрака на полу, с клиньями и шашками."],["Левая обезьяна","Обезьяна в куртке сидит у доски."],["Бокал","Бокал в руке левой обезьяны."],["Шляпа с пером","Петушиное перо на шляпе правой обезьяны."],["Кувшин","Кувшин у ног левой обезьяны."],["Надпись","«D Teniers in et excud cum privilegio»."]]},"dstereo":{"title":"Мужчины играют в домино за столом (стереофотография)","artist":"Неизвестный автор","date":"1850–1880","place":"Неизвестно (надпись по-нидерландски)","game":"Домино","medium":"Альбуминовый отпечаток (стереофотография)","size":"8,5 × 17,0 см","credit":"","p":["Стереофотография: два почти одинаковых снимка рядом. В стереоскопе они сливаются в одну объёмную сцену. У левого края от руки написано «Het dominospel» (игра в домино).","Стол вынесли на солнце перед зданием, мужчины без сюртуков держат кости домино. Двое стоя следят за игрой; правый игрок в белой шапочке. Поскольку все должны были замереть, сцену, вероятно, поставили для камеры."],"spots":[["Кости на столе","Кости домино в руках, лицом вниз."],["Мужчина в белой шапочке","Сидит справа со своими костями."],["Мужчина с шейным платком","Стоит и смотрит на игру сверху."],["Мужчина слева","Молодой человек, облокотившись, смотрит в свои кости."],["Надпись","«Het dominospel.» у левого края."],["Второй снимок","Правое фото, сделанное с чуть смещённой точки: вместе они дают объём."]]},"gojo":{"title":"Две женщины играют в го","artist":"Неизвестный автор","date":"1870–1891","place":"Япония","game":"Вероятно, го","medium":"Раскрашенный от руки альбуминовый отпечаток","size":"9,0 × 13,5 см","credit":"","p":["Чёрно-белая фотография, раскрашенная от руки кистью. Такие снимки делали в ателье Иокогамы и других городов как сувениры для иностранцев. Этот был вклеен в альбом фотографий о путешествии в Манилу.","На фоне убранства ниши и ширмы две женщины сидят по обе стороны доски на ножках; левая ставит камень. На доске белые и чёрные камни — вероятно, го, хотя в записи музея сказано «настольная игра». На подносе впереди сладости и посуда."],"spots":[["Доска и камни","Толстая доска на ножках с белыми и чёрными камнями."],["Рука, делающая ход","Левая женщина ставит камень."],["Женщина слева","Обернулась к нам; оби завязан большим узлом."],["Женщина справа","В полосатом кимоно, рука у доски."],["Поднос и посуда","Сладости и чашки впереди."],["Цветы","Ваза с цветами на подставке позади."]]},"meade":{"title":"Двое мужчин играют в шахматы","artist":"Чарльз Ричард Мид и Генри Уильям Мэтью Мид","date":"1852","place":"США","game":"Шахматы","medium":"Дагеротип","size":"6,9 × 8,3 см","credit":"","p":["Дагеротип из ателье братьев Мид — уроженцев Англии, работавших в Америке. Дагеротип создаёт изображение прямо на посеребрённой медной пластине, поэтому каждый снимок уникален и не тиражируется; этот хранится в маленьком кожаном футляре за золочёным паспарту.","Двое молодых людей сидят у шахматной доски на маленьком столике; левый держит пальцы на фигуре. Правый, приложив руку к груди, изучает позицию. Так как им нужно было долго не двигаться, ход, вероятно, разыгран для снимка."],"spots":[["Шахматная доска","Доска и белые фигуры на столике под цветастой тканью."],["Мужчина слева","Пальцы на фигуре."],["Мужчина справа","Смотрит на доску."],["Рука на груди","Задумчивая рука правого игрока."],["Ткань","Маленький столик под цветастой тканью."],["Золочёное паспарту","Рамка и футляр, защищающие пластину."]]},"weiqidai":{"title":"Пейзаж с даосскими бессмертными, играющими в вэйци","artist":"Приписывается Дай Цзиню","date":"Династия Мин, XV–XVI века","place":"Китай","game":"Вэйци (го)","medium":"Вертикальный свиток; тушь и краски по шёлку","size":"175,2 × 106,7 см","credit":"","p":["Большой вертикальный свиток, приписываемый минскому художнику Дай Цзиню (ок. 1388–1462). Уроженец Чжэцзяна, известный мощными пейзажами, позднее он считался основателем школы Чжэ. Под отвесными скалами и огромным деревом люди изображены маленькими.","В тени на земле двое бессмертных сидят у расчерченной доски для вэйци, рядом блюдо с плодами и кувшин. Сгорбленная фигура слева напоминает дровосека, который смотрел на игру бессмертных в горах, пока не сгнило топорище (легенда Ланькэ), хотя название в музее говорит лишь о бессмертных за вэйци."],"spots":[["Доска","Доска с бортиком и тонкой сеткой."],["Бородатый бессмертный","Бессмертный с длинной бородой, сидит спокойно."],["Бессмертный в синей шапке","Склонился над доской; у колена чаша с камнями."],["Сгорбленная фигура","Смотрит на доску слева; возможно, дровосек из легенды."],["Плоды и кувшин","Блюдо и кувшин за доской."],["Подпись и печати","Подпись и две красные печати справа вверху."]]},"reise":{"title":"Путешествие вокруг света, по воде и по суше","artist":"Неизвестный автор","date":"XIX век","place":"Вероятно, немецкоязычные земли","game":"Гонка с одной костью на ставки","medium":"Литография","size":"42,5 × 33,7 см","credit":"","p":["Игровой лист с немецким заголовком «Путешествие вокруг света, по воде и по суше: новая и занимательная игра в кости». На круглой доске поля от 1 до 41 с изображениями воздушного шара, парусников, парохода, паровоза, людей разных народов и прочего. Внизу справа — «No. 107».","Ниже напечатаны правила по-немецки, по-английски, по-нидерландски и по-французски. Каждый сначала платит 15 марок в общую «дорожную кассу», затем по очереди бросает одну кость и ставит свою фишку. За большую картинку дают 2 марки, поле без картинки стоит 2 марки штрафа, а кто дойдёт до 41, забирает всё остальное."],"spots":[["41: дилижанс","Цель в центре: дилижанс с пассажирами и кучером."],["1: англичанин","Стартовое поле, «Engländer» в цилиндре."],["Воздушный шар","Поле с шаром в небе."],["Парусник","Корабль под всеми парусами."],["Паровоз","Дымящий паровоз."],["Правила","Правила на четырёх языках."]]},"huchten":{"title":"Игра в кости на жизнь","artist":"Ян ван Хухтенбург","date":"1680–1720","place":"Нидерланды","game":"Кости","medium":"Холст, масло","size":"67,5 × 76,0 см","credit":"","p":["Работа нидерландского художника Яна ван Хухтенбурга (1647–1733), известного батальными сценами, с подписью слева внизу. Музейное название — «Игра в кости на жизнь». У стен крепости двое заключённых бросают кости на барабан, вокруг офицеры и солдаты.","Справа в глубине стоит виселица, слева со стены крепости смотрят солдаты. Вероятно, приговорённые солдаты бросают жребий костями, кого казнят. Один заключённый указывает на барабан, другой, стоя на коленях, смотрит на бросок."],"spots":[["Барабан и кости","Барабан служит столом для броска."],["Указывающий заключённый","Стоя, указывает на барабан."],["Коленопреклонённый заключённый","В белой рубахе склонился над барабаном."],["Офицер на коне","В шляпе, смотрит сверху с коня."],["Виселица","Виселица справа вверху."],["Солдаты на стене","Солдаты, глядящие со стены крепости."]]},"vertu":{"title":"Игра добродетели (Spel der Deugd)","artist":"Ян Геррится Виссер (замысел Й. Формана)","date":"1798","place":"Нидерланды","game":"Азартная игра на двух костях","medium":"Резцовая гравюра, офорт и высокая печать","size":"56,9 × 38,0 см","credit":"","p":["Большой игровой лист с нидерландско-французским названием «Игра добродетели». В храме с колоннами в центре восседает Добродетель, слева стоит Процветание, справа — Бедность. На колоннах медальоны добродетелей — Искренности, Благодарности, Любви, а на постаментах — пороки: Скупость, Гордыня, Лень.","По правилам внизу играют двумя костями или тянут жребий. С костями игроки ставят вместе 63 и бросают по очереди по ходу солнца. Каждый бросок означает добродетель или порок: дубль шестёрок, Добродетель, забирает банк, а дубль единиц, Порок, платит восемь. Под каждой картинкой «T» — сколько берут, «B» — сколько платят."],"spots":[["Заголовок","«SPEL DER DEUGD» во фронтоне."],["Добродетель","Добродетель на троне в центре; дубль шестёрок забирает всё."],["Процветание","Процветание с рогом изобилия."],["Порок","Дубль единиц, Порок: ребёнок, поднявший кубок."],["Скупость","Скупость на постаменте; «B» и кости показывают платёж."],["Правила","Плотно напечатанные правила внизу."]]},"charros":{"title":"Чарро-контрабандисты: игра в кости","artist":"Хосе Гуадалупе Посада","date":"Без даты","place":"Мексика","game":"Гонка с тремя костями","medium":"Литография","size":"29,9 × 40,4 см","credit":"","p":["Игра-гонка с рисунками Посады под названием «LOS CHARROS CONTRABANDISTAS / JUEGO DE DADOS» («Чарро-контрабандисты / Игра в кости»). Внизу — имя типографии А. Ванегаса Арройо в Мехико, справа внизу подпись Посады. По углам скачут чарро — мексиканские всадники в сомбреро.","Круглые поля в верёвочной рамке вьются по всей доске, на них звери, люди, поезд и прочее. «Объяснение» справа вверху говорит, что бросают три кости. Три единицы с первого броска — победа; череп — проигрыш; на олене берут из банка, на разбойниках платят, а на льве стоят, пока не придёт другой."],"spots":[["Заголовок","«LOS CHARROS CONTRABANDISTAS / JUEGO DE DADOS»."],["Объяснение","Правила под словом «EXPLICACION»."],["Игроки","Люди за столом играют на доске, слева внизу."],["Кости","Три кости посреди доски."],["Чарро на коне","Скачущий чарро с лассо."],["Типография","«IMPRENTA DE A. VANEGAS ARROYO, MÉXICO»."]]},"snuffwq":{"title":"Табакерка с игроками в вэйци","artist":"Китай","date":"Династия Цин, марка и период Даогуан (1820–50)","place":"Китай","game":"Вэйци (го)","medium":"Фарфор, роспись надглазурными эмалями","size":"Высота 5,7 см","credit":"","p":["Флакончик для нюхательного табака из цинского Китая. По записи музея, на нём марка девиза Даогуан, время — 1820–50 годы. На белом фарфоровом тулове высотой около шести сантиметров эмалями написаны горный пейзаж и фигуры.","У скалы, похожей на грот, двое стариков сидят у доски для вэйци на синей подставке; левый вот-вот поставит камень. За ним наблюдает мальчик с посохом. Сюжет, вероятно, напоминает о дровосеке, смотревшем на игру бессмертных."],"spots":[["Доска","Доска на синей подставке с тонкой сеткой."],["Бородатый старец","В лиловом халате тянется к доске."],["Старец напротив","Сидит справа, подняв руку."],["Мальчик с посохом","Смотрит сзади."],["Грот","Скала, похожая на пещеру."],["Пробка","Зелёная пробка."]]},"ostade":{"title":"Игроки в триктрак в трактире","artist":"Адриан ван Остаде","date":"1653","place":"Нидерланды (Харлем)","game":"Триктрак (родственник нард)","medium":"Офорт","size":"8,5 × 7,4 см","credit":"","p":["Офорт размером с ладонь харлемского художника Остаде, известного крестьянскими сценами, с подписью «A. ostade» внизу. В тёмном трактире свет из окна со свинцовым переплётом падает на людей.","За столом слева двое сидят над доской для триктрака, третий заглядывает сзади. Справа мужчина откинулся к стене с кружкой в руке. На полу валяется большой кувшин — похоже на ленивый день в трактире."],"spots":[["Доска","Доска для триктрака на столе."],["Левый игрок","Мужчина в шляпе перед доской."],["Правый игрок","Склонился над доской."],["Зритель","Мужчина стоит сзади и смотрит."],["Отдыхающий","Сидит у стены с кружкой."],["Окно с переплётом","Окно с ромбами стёкол, откуда идёт свет."]]},"lenain":{"title":"Игроки в кости","artist":"Последователь Матьё Ленена","date":"1630–1680","place":"Франция","game":"Кости","medium":"Холст, масло","size":"92,8 × 119,7 см","credit":"","p":["Работа последователя Матьё, младшего из французских братьев Ленен. Музей отмечает, что набросок похожей композиции работы Габриэля де Сент-Обена хранится в Национальной библиотеке в Париже.","Трое мужчин сидят под открытым небом у маленького круглого стола и бросают кости; двое смотрят, левый прижимает к себе бутылку. Справа две поджарые борзые, за проёмом — широкий пейзаж. Белые точки на столе — это кости."],"spots":[["Кости на столе","Кости на круглом столе."],["Мужчина в светлой шляпе","Сидит и тянется проверить бросок."],["Мужчина в чёрном","Молодой человек стоит, рука на бедре."],["Мальчик позади","Следит за игрой из-за стола."],["Мужчина с бутылкой","Слева, улыбается нам."],["Две борзые","Поджарые собаки справа."]]},"tunisie":{"title":"Игра в карты у арабского кафе (тунисский отдел, выставка в Антверпене)","artist":"Неизвестный автор (печать Ш. Бернхефта)","date":"1894","place":"Бельгия (Антверпен)","game":"Карты","medium":"Фототипия","size":"15,4 × 21,6 см","credit":"","p":["Один из 49 листов о Всемирной выставке в Антверпене 1894 года: вверху «EXPOSITION UNIVERSELLE D’ANVERS 1894», внизу «Тунис. Игра в карты у арабского кафе». Напечатал его Бернхефт, придворный фотограф в Люксембурге.","Снимок сделан на площади с куполами и башней, построенной для тунисского отдела выставки. Мужчины в тунисской одежде играют в карты за маленькими столиками с изразцами; один курит кальян, рядом поднос с чашками. Справа сидят посетители в костюмах — вероятно, это был показ жизни далёкой страны."],"spots":[["Карточный стол","Мужчины с картами у столика с изразцами."],["Кальян","Трубка кальяна у мужчины слева."],["Посетители в костюмах","Мужчины в костюмах справа, вероятно, гости выставки."],["Поднос с чашками","Маленькие чашки под столом."],["Купола и башня","Здания в тунисском стиле, построенные для выставки."],["Подпись","«TUNISIE» и «PARTIE DE CARTES DEVANT UN CAFÉ ARABE»."]]},"laghouat":{"title":"Каиды из окрестностей Лагуата","artist":"Неизвестный автор","date":"1880–1890","place":"Алжир (окрестности Лагуата)","game":"Вероятно, домино","medium":"Альбуминовый отпечаток","size":"20,9 × 27,0 см","credit":"","p":["Фотография под названием «Алжирские типы. Каиды из окрестностей Лагуата», вклеенная в альбом, с напечатанным номером «239». Каидом во французском Алжире называли местного главу.","Мужчины в белых одеждах сидят на циновке у глинобитной стены и выкладывают продолговатые кости на низкий столик. Судя по раскладке, это, вероятно, домино, хотя в записи музея сказано лишь «игра». Впереди поднос с чаем и снятые туфли."],"spots":[["Кости на столике","Продолговатые кости, выложенные в ряд."],["Поднос с чаем","Стаканы и чайник на подносе впереди."],["Туфли","Обувь, оставленная у циновки."],["Стоящая фигура","Кто-то стоит у стены и смотрит."],["Глинобитная стена","Шершавая земляная стена позади."],["Циновка","Плетёная циновка, на которой сидят."]]},"hangong":{"title":"Придворные дамы (Весеннее утро во дворце Хань), фрагмент","artist":"Копия по Цю Ину","date":"Династия Цин (1644–1911)","place":"Китай","game":"Вэйци (го)","medium":"Горизонтальный свиток; тушь и краски по шёлку","size":"36,2 × 454,4 см (весь свиток)","credit":"","p":["Фрагмент горизонтального свитка длиной больше четырёх с половиной метров — цинской копии композиции минского художника Цю Ина (1494–1552). Во дворце весенним днём придворные дамы, девочки и служанки качаются на качелях, играют, любуются пионами, музицируют, играют на цине, кормят попугая и рыб.","В этой сцене за балюстрадой две женщины сидят друг против друга у доски для вэйци, а другие склонились посмотреть. Впереди — «учёный камень» в чаше в форме лотоса, служанки несут инструменты и свёртки. Как отмечает музей, свиток идеализирует жизнь женщин во внутренних покоях дворца."],"spots":[["Доска","Доска для вэйци на столике за балюстрадой."],["Играющая","Женщина в бледно-лиловом тянется к доске."],["Зрительницы","Женщины, склонившиеся над партией."],["Дама с веером","Женщина с круглым веером между колоннами."],["«Учёный камень»","Синий камень в чаше в форме лотоса."],["Служанка с инструментом","Служанка несёт, вероятно, пипу."]]},"homerbg":{"title":"Нарды","artist":"Уинслоу Хомер","date":"Ок. 1877","place":"США","game":"Нарды (бэкгаммон)","medium":"Торцовая гравюра на дереве","size":"","credit":"","p":["Торцовая гравюра по рисунку американского художника Уинслоу Хомера (1836–1910), который в молодости много рисовал иллюстрации для подобных гравюр. Внизу напечатано «396.—BACKGAMMON.—WINSLOW HOMER.», так что это, вероятно, нумерованный лист из книги или журнала.","Две женщины сидят друг против друга на нарядном диване и играют в нарды на доске, положенной им на колени. На доске лежит что-то круглое и белое, но что это — неясно. Складки длинных юбок и завитые подлокотники дивана вырезаны тонкими линиями."],"spots":[["Доска","Доска на коленях у двух женщин."],["Женщина слева","С подобранными волосами, тянется к доске."],["Женщина справа","Подалась вперёд, разглядывая доску."],["Подлокотник","Подлокотник в виде завитка."],["Юбки","Длинные юбки со складками в тонких линиях."],["Подпись","«396.—BACKGAMMON.—WINSLOW HOMER.» внизу."]]},"chessst":{"title":"Мужчина и женщина играют в шахматы (стереофотография)","artist":"Неизвестный автор","date":"1852–1858","place":"Неизвестно","game":"Шахматы","medium":"Стереофотография, раскрашенная","size":"8,3 × 16,5 см","credit":"","p":["Пара снимков, наклеенных как стереофотография, известная по-английски как «The Chess Players». В стереоскопе доска и фигуры словно выступают вперёд. Поверх чёрно-белого изображения раскрашены красная занавесь и жёлтое платье.","Женщина в жёлтом взялась за фигуру, а мужчина напротив, видимый со спины, изучает доску. Красные и белые фигуры стоят посреди партии, но сцена, вероятно, поставлена в ателье. Такие стереоснимки домашних сцен широко продавались в середине XIX века."],"spots":[["Доска и фигуры","Красные и белые фигуры на клетчатой доске."],["Рука, делающая ход","Рука женщины на фигуре."],["Женщина","В жёлтом платье с белым воротником, склонилась к доске."],["Мужчина","Сидит спиной к нам."],["Красная занавесь","Раскрашенная занавесь позади."],["Второй снимок","Правый вид; в стереоскопе пара обретает глубину."]]},"corrida":{"title":"Игра в кости «Коррида» (Corrida de Toros)","artist":"Хосе Гуадалупе Посада","date":"1898","place":"Мексика","game":"Гонка на двух костях на ставки","medium":"Фотоцинкография высокой печати на веленевой бумаге","size":"40,4 × 30,0 см","credit":"","p":["Игра-гонка с рисунками Посады под названием «CORRIDA DE TOROS» («Коррида»). Поля идут спиралью и показывают по порядку приёмы и моменты боя быков — от поля 1 снаружи к центру. В середине — арена, внизу — название типографии Антонио Ванегаса Арройо.","По «Объяснению» внизу, играют двое и больше, каждый делает ставку и ходит, бросая две кости. Пять, «прыжок с шестом», ведёт на 10; двенадцать, «бык поднял пикадора на рога», — платят и пропускают ход; 28, «грудной пасе», — начинают сначала. Кто дойдёт до 32, «быка уволакивают», забирает все ставки."],"spots":[["Заголовок","Слова «CORRIDA DE TOROS»."],["Арена","Здание арены в центре спирали."],["Поле 1","Старт у входа в спираль."],["Голова быка","Рогатая голова быка справа вверху."],["Тореро","Портрет тореро слева внизу."],["Объяснение","Напечатанное внизу «EXPLICACION»."]]},"ambrocards":{"title":"Трое мужчин играют в карты","artist":"Неизвестный автор (американский)","date":"1865","place":"США","game":"Карты","medium":"Амбротип","size":"14,0 × 11,0 см","credit":"","p":["Амбротип — тонкий негатив на стекле с чёрной подложкой, отчего он выглядит позитивом. Дешевле дагеротипа, он был широко распространён в Америке в 1850–60-х годах. Этот снимок вставлен за золочёное паспарту в футляр, обитый красным бархатом.","На гладком фоне трое мужчин сидят за маленьким столом с картами в руках. Левый в котелке, правый в кепке, у обоих сигары во рту; мужчина в центре, в тёмном пиджаке, смотрит на нас. Вероятно, они позировали так, будто игра в разгаре."],"spots":[["Руки","Руки с картами над столом."],["Мужчина в котелке","Слева, с сигарой."],["Мужчина в центре","В тёмном пиджаке, смотрит на нас."],["Мужчина в кепке","Справа, с сигарой."],["Золочёное паспарту","Тиснёная золотая рамка вокруг изображения."],["Футляр","Футляр, обитый красным бархатом."]]},"morphy":{"title":"Пол Морфи, чемпион по шахматам","artist":"Уинслоу Хомер","date":"1859","place":"США","game":"Шахматы","medium":"Торцовая гравюра на дереве","size":"","credit":"","p":["Гравированный на дереве портрет с подписью «PAUL MORPHY, THE CHESS CHAMPION» по рисунку Уинслоу Хомера (1836–1910), тогда ещё молодого иллюстратора. Морфи (1837–1884) из Нового Орлеана в 1858–59 годах объехал Европу, побеждая одного ведущего мастера за другим, и вернулся домой знаменитым.","Молодой Морфи сидит, положив левую руку на край доски, рядом стоят король, ладья, пешки и другие фигуры. Лист сделан в 1859 году, когда он вернулся знаменитостью, и, вероятно, был напечатан как иллюстрация в газете или журнале."],"spots":[["Фигуры","Король, ладья, пешки и другие на доске."],["Рука на доске","Левая рука на краю доски."],["Лицо Морфи","Чемпион, едва перешагнувший двадцать лет."],["Галстук-бабочка","Аккуратный воротник."],["Рука на колене","Правая рука лежит на колене."],["Заголовок","«PAUL MORPHY, THE CHESS CHAMPION» внизу."]]},"dutton":{"title":"Семья Даттон в гостиной Шерборн-парка, Глостершир","artist":"Иоганн Цоффани","date":"Ок. 1772","place":"Англия","game":"Карты","medium":"Холст, масло","size":"101,5 × 127,0 см","credit":"","p":["Работа Иоганна Цоффани (1733–1810), уроженца Германии, сделавшего карьеру в Англии. «Conversation piece» — непринуждённый семейный портрет — появился в Англии XVIII века и стал очень популярен. Действие происходит в гостиной Шерборн-парка в Глостершире.","По словам музея, отец с дочерью и мать с сыном обдумывают следующий ход в карточной игре. Семья недавно потеряла близкого человека, поэтому родители в глубоком трауре, в чёрном, а дети в полутрауре — лиловом, белом и сером."],"spots":[["Карточный стол","Стол с зелёным сукном и картами."],["Отец","В чёрном, с картами в руке."],["Дочь","В белом, смотрит в свои карты."],["Сын","В сером, с картами в руке."],["Мать","В чёрном траурном платье."],["Камин","Мраморный камин с горящим огнём."]]},"whist":{"title":"Рождественские учёные: комбинированная партия в вист","artist":"Джеймс Бретертон (вероятно, по рисунку Г. У. Банбери)","date":"1773","place":"Англия","game":"Вист (карты)","medium":"Офорт","size":"26,5 × 39,6 см","credit":"","p":["По словам музея, это сатира на учёных Кембриджа. Слева внизу, похоже, написано «H. W. Bunbury del. 1772», справа — «J. Bretherton f.»; лист издан в 1773 году лавкой на Нью-Бонд-стрит в Лондоне. На стене висят академические шапочки.","Четверо джентльменов играют в вист и корчат друг другу рожи. В вист играют две пары, так что «комбинированная партия» в названии — вероятно, каламбур. Сзади один показывает пальцами насмешливый знак над чужой головой. Рядом двое слуг и две собаки."],"spots":[["Карты на столе","Сыгранные карты на столе."],["Учёный в парике","Учёный в большом парике прижимает карты."],["Знак пальцами","Мужчина сзади поднял пальцы над чужой головой."],["Служанка","Служанка в шляпе с подносом."],["Шапочки","Университетские шапочки на стене."],["Собака справа","Маленькая лающая собака справа внизу."]]},"hey":{"title":"Трое мужчин за шахматами","artist":"Пауль Хей","date":"1877–1952","place":"Германия","game":"Шахматы","medium":"Гравюра (вероятно, офорт)","size":"19,3 × 26,0 см","credit":"","p":["Гравюра немецкого художника и иллюстратора Пауля Хея (1867–1952). Трое пожилых мужчин склонились над одной доской; тонкие наслоенные линии передают глубокие морщины и белые бороды.","Как отмечено в записи музея, левый подпёр подбородок рукой, а правый держит сигару и тянется к фигурам. Слева на столе две кофейные чашки, стакан и спичечный коробок. Вероятно, это партия в кафе."],"spots":[["Шахматная доска","Доска и фигуры на столе."],["Мужчина, подперший подбородок","Белобородый, в раздумье."],["Мужчина посередине","Подался вперёд и тянется к фигуре."],["Мужчина справа","Заглядывает сзади."],["Рука с сигарой","Сигара между пальцами."],["Кофе и спички","Две чашки, стакан и коробок слева."]]},"artful":{"title":"Хитрая карта, или одна лишняя для бабушки. Черви — козыри!","artist":"Неизвестный автор","date":"1852–1863","place":"Вероятно, Великобритания","game":"Карты","medium":"Стереофотография, раскрашенная","size":"8,4 × 17,4 см","credit":"","p":["Английское название — «The artful card, or, one too many for granny. Hearts are trumps!». Шуточная сценка о том, как бабушку обходят хитрой картой, превращённая в пару стереоснимков. Судя по английскому названию, сделана, вероятно, в Великобритании.","За круглым столом бабушка и девочка играют в карты, а девушку в зелёном с картами в руке обнимает сзади молодой человек. «Черви — козыри», вероятно, каламбур на масть и на любовь. Комната с прялкой и посудным шкафом — наверняка декорация ателье."],"spots":[["Карты девушки","Карты в руках девушки в зелёном."],["Молодой человек","Его рука на её плече сзади."],["Бабушка","Пожилая женщина в платке смотрит в карты."],["Девочка","С улыбкой выкладывает карту."],["Стол","Круглый стол с картами и мелочами."],["Посудный шкаф","Застеклённый шкаф с посудой."]]},"cezcards":{"title":"Этюд для «Игроков в карты»","artist":"Поль Сезанн","date":"1890–92","place":"Франция","game":"Карты","medium":"Акварель и графитный карандаш на бежевой веленевой бумаге","size":"36,2 × 48,5 см","credit":"","p":["В 1890-х годах в Эксе, на юге Франции, Сезанн написал несколько картин с мужчинами, играющими в карты. Это акварельный этюд к той серии: усатый мужчина в шляпе сидит за столом и смотрит в свои карты.","Поверх карандашных линий лёгкие синие и серые заливки передают складки куртки и тяжесть тела. Правая часть и дальний край стола оставлены незаконченными; цвет лежит только вокруг фигуры. Говорят, моделями были местные работники."],"spots":[["Лицо","Опустив глаза под шляпой, смотрит в карты."],["Карты","Карты в обеих руках."],["Стол","Стол, намеченный только карандашом."],["Стул","Спинка стула слева."],["Куртка","Складки, построенные синим и серым."],["Незаконченное","У ножек стола остались одни линии."]]},"vuillardck":{"title":"Партия в шашки, из альбома «Пейзажи и интерьеры»","artist":"Эдуар Вюйар","date":"1899","place":"Франция","game":"Шашки","medium":"Цветная литография на серовато-слоновой китайской бумаге","size":"36,9 × 28,5 см","credit":"","p":["Первый лист альбома цветных литографий «Пейзажи и интерьеры» французского художника Вюйара, изданного маршаном Амбруазом Воларом и отпечатанного литографом Огюстом Кло.","В комнате, сплошь покрытой узорчатыми обоями, бородатый мужчина сидит за шашечной доской, а женщина в клетчатом платье стоит, подперев подбородок, и смотрит. Фигуры, обои и диван растворяются в плоских цветах и узорах; чётко выделяются лишь чёрно-белые клетки доски."],"spots":[["Доска","Чёрно-белая шашечная доска."],["Бородатый мужчина","Сидит у доски."],["Стоящая женщина","В клетчатом платье, рука у подбородка."],["Обои","Обои, сплошь в вьющихся линиях."],["Цветастая подушка","Узорчатая ткань слева внизу."],["Лампа","Тонкий силуэт лампы у стены."]]},"cruikchess":{"title":"Партия в шахматы","artist":"Джордж Крукшенк по рисунку капитана Фредерика Марриета","date":"1814","place":"Англия","game":"Шахматы","medium":"Офорт, раскрашенный от руки","size":"23,8 × 34,5 см","credit":"","p":["Лист английского карикатуриста Крукшенка по наброску Марриета, морского офицера и впоследствии романиста; издала его в Лондоне Ханна Хамфри. Внизу — заголовок «GAME of CHESS».","За столом со свечами двое пожилых джентльменов сидят над шахматной доской. За спиной у каждого стоит зритель: левый прикладывает палец к губам, правый разглядывает доску в лорнет. Вероятно, это насмешка над болельщиками, которые не могут молчать."],"spots":[["Доска","Шахматная доска с белыми и чёрными фигурами."],["Свечи","Две свечи освещают доску."],["Шикающий","Зритель, приложивший палец к губам."],["Человек с лорнетом","Зритель, разглядывающий доску в лорнет."],["Спящая собака","Собака спит под столом."],["Заголовок","«GAME of CHESS» внизу."]]},"domino98":{"title":"Женщина и девочка играют в домино за столом","artist":"Неизвестный автор (американский)","date":"Ок. 1898","place":"США","game":"Домино","medium":"Альбуминовый отпечаток, наклеенный на стекло","size":"40,8 × 51,1 см","credit":"","p":["Большая фотография, вероятно, из американского ателье, наклеенная на стекло. Женщина в белом и кудрявая девочка сидят по обе стороны столика, украшенного цветами.","На столе лежат кости домино, и женщина выкладывает одну. Девочка, подперев подбородок, смотрит. Шторы, нарядный шкаф и картины на стене — скорее всего, декорации ателье."],"spots":[["Кости","Белые кости домино на столе."],["Девочка","Подперев подбородок, смотрит на кости."],["Женщина","В белом, выкладывает кость."],["Цветы","Ваза с цветами на столе."],["Шкаф","Нарядный шкаф справа в глубине."],["Надпись","Белые буквы справа внизу."]]},"langkat":{"title":"Альберт Глазер играет в карты с двумя друзьями на лодке, Лангкат, Суматра","artist":"Неизвестный автор (H. Ernst & Co.)","date":"1895–1905","place":"Индонезия (Лангкат, Суматра)","game":"Карты","medium":"Фотография","size":"17,5 × 22,8 см","credit":"","p":["Фотография, сделанная в Лангкате на севере Суматры. Внизу справа — слепое тиснение ателье «H. Ernst & Co. / Bindjey Langkat», а на обороте от руки записано, что человек посередине — Альберт Глазер, брат одной дамы.","На палубе лодки под навесом трое мужчин в белом сидят за столом с картами в руках. На столе карты и мелкие предметы вроде монет, у правого мужчины — бутылка. Белая одежда и навес говорят о жизни в жарком климате."],"spots":[["На столе","Розданные карты и мелочь вроде монет."],["Глазер","Человек посередине раскрыл карты; надпись на обороте называет его."],["Мужчина слева","Виден вполоборота, с картами."],["Мужчина справа","С усами, с картами в руке."],["Бутылка","Бутылка рядом с правым мужчиной."],["Навес","Листья, свисающие с навеса."]]},"chatur":{"title":"Партия в чатурангу","artist":"Неизвестный автор","date":"1805–1815","place":"Индия","game":"Чатуранга","medium":"Гуашь и золото, кисть","size":"16,2 × 9,8 см (изображение)","credit":"","p":["Индийская миниатюра. Согласно записи музея, две женщины играют в чатурангу — настольную игру, а служанка держит опахало от мух. Чатуранга — древняя индийская игра, которую считают предком шахмат.","Под белыми арками, на красном ковре, женщина в тёмно-синем и женщина в оранжевом сидят друг против друга у клетчатой доски. Женщина в оранжевом протягивает руку, будто что-то говорит. Изображение обрамлено тёмно-красной каймой с чёрными и белыми линиями."],"spots":[["Доска","Клетчатая доска на красном ковре."],["Женщина в синем","В золотых украшениях, тянется к доске."],["Женщина в оранжевом","Напротив, с протянутой рукой."],["Служанка","Стоит позади."],["Опахало","Его держит служанка."],["Красная кайма","Тёмно-красная рамка с чёрными и белыми линиями."]]},"shabbarat":{"title":"Вечер в женских покоях","artist":"Неизвестный автор","date":"1760–1770","place":"Индия","game":"Чаупар (пачиси)","medium":"Гуашь и золото, кисть","size":"34,3 × 25,6 см","credit":"","p":["Индийская миниатюра. Согласно записи музея, четыре женщины играют в настольную игру на широком дворе дворца — в чаупар, или пачиси. Они сидят вокруг крестообразной матерчатой доски.","Женщина впереди справа держит три длинные кости и вот-вот бросит. Рядом, опершись на валик, сидит самая знатная дама. Ночь, но по всей террасе стоят светильники, а на далёких городских стенах горят бесчисленные огни. В записи предполагается, что празднуют мусульманский праздник Шаб-э Барат."],"spots":[["Крестообразная доска","Доска в форме креста, разостланная на полу."],["Женщина с костями","Впереди, с длинными костями."],["Дама на валике","Самая знатная дама."],["Служанка","Подходит с подносом."],["Светильник","Свеча под стеклянным колпаком."],["Дальний павильон","Сад с фонтаном, павильон и огни города."]]},"govase":{"title":"Яйцевидная ваза с женщинами, играющими в го","artist":"Неизвестный автор (печать «Тан Цзиньтан»)","date":"1724","place":"Китай (Гуандун)","game":"Го (вэйци)","medium":"Фарфор, надглазурные эмали, золочение","size":"Высота 15,3 см","credit":"","p":["Китайская ваза из очень тонкого фарфора, расписанная эмалями. На обороте надпись: «картина партии в го, написанная в день Праздника цветов года цзячэнь в уютном доме на Жемчужной реке в Линнане», и красная печать «Тан Цзиньтан». Ваза входила в фарфоровую коллекцию гаагского собирателя Жана Теодора Руайе.","Две женщины сидят друг против друга у доски для го на столе; левая держит чашу с камнями. Справа две женщины и двое детей склонились посмотреть. На подставке позади — древности, среди них ваза с павлиньими перьями и коралл."],"spots":[["Доска","Доска для го на столе, с чёрными и белыми камнями."],["Игрок слева","С чашей камней, указывает пальцем."],["Игрок справа","Склонилась над доской."],["Зрительницы","Женщины смотрят из-за спин."],["Павлиньи перья и коралл","В вазе на подставке."],["Чаша с камнями","В руке у левой женщины."]]},"yokihi":{"title":"Мужчина играет в нарды с дамой (император Сюань-цзун и Ян Гуйфэй)","artist":"Неизвестный автор (суримоно)","date":"1822","place":"Япония","game":"Бан-сугороку (японские нарды)","medium":"Цветная ксилография с металлическими пигментами","size":"21,6 × 19,1 см","credit":"","p":["Суримоно — роскошная гравюра, соединяющая изображение и стихи, напечатанная на плотной бумаге с металлическими порошками и заказанная поэтами в подарок друзьям. На этом листе одно стихотворение и имя поэта — Татибана-но Гоэн.","Согласно записи музея, танский император Сюань-цзун (685–762) играет в сугороку со своей любимой наложницей Ян Гуйфэй (719–756); эта игра родственна нардам и триктраку. На доске в виде ящика, стоящей на красной подставке, — чёрные и белые шашки."],"spots":[["Доска","Доска для сугороку в виде ящика на красной подставке."],["Ян Гуйфэй","С цветами в волосах, рука на доске."],["Сюань-цзун","Подперев подбородок, смотрит на доску."],["Стихотворение","Стих и имя поэта слева вверху."],["Ширма","Ширма с горами позади."],["Подпись и печать","Подпись и красная печать справа внизу."]]},"disderi":{"title":"Мужчины в костюмах мореходов играют в карты","artist":"Disdéri & Cie","date":"1850–1890","place":"Франция (Париж)","game":"Карты","medium":"Альбуминовый отпечаток (кабинетная визитка)","size":"8,6 × 5,3 см","credit":"","p":["Фотография формата «карт-де-визит» из альбома, на обороте напечатано «Disdéri & Cie, бульвар Итальянцев, 8, Париж». Дисдери — фотограф, сделавший популярными карт-де-визит, маленькие портреты, которые печатали пачками, как визитные карточки.","Мужчины в старинной одежде — треуголки, длинные кафтаны, белые чулки — играют в карты за узорчатым столом. В записи музея костюм назван костюмом мореходов, но, вероятно, это театральный или маскарадный наряд. Средний мужчина встал, чтобы заглянуть на стол."],"spots":[["Стол","Стол с узорчатой каймой, на нём карты и кружки."],["Стоящий мужчина","В треуголке склонился над столом."],["Мужчина слева","Сидит с картами в руке."],["Мужчина справа","В треуголке, с картами в руке."],["Туфли с пряжками","Белые чулки и туфли с пряжками."],["Золочёная рамка","Золотая кайма паспарту."]]},"gans":{"title":"Игра в гусёк (спираль из 74 полей)","artist":"Ян Оортман (старший) по рисунку Даниэля Виллема Стопендала","date":"1763–1823","place":"Нидерланды","game":"Гусёк (гонка на костях)","medium":"Ксилография, раскрашенная синим, красным и зелёным","size":"40,8 × 46,8 см","credit":"","p":["Спиральная игра-гонка, напечатанная в Нидерландах. По словам музея, поля идут от 1 до 74, на некоторых есть картинки. Доску вырезал Ян Оортман по рисунку Стопендала, чьё имя стоит справа внизу со словом «invenit».","Цель — поле 74, храм на берегу моря на закате, в центре. На полях слова «LEER GELD» (плата за учёбу), «DWAALWEG» (ложный путь), «DOMHEID / WYSHEID» (глупость / мудрость) и скелет с косой — «EINDE» (конец); вероятно, это нравоучительная игра о жизненном пути."],"spots":[["74: храм","Цель: храм на берегу на закате."],["1: старт","Первое поле слева внизу."],["Плата за учёбу","Поле «LEER GELD», вероятно, где платят."],["Ложный путь","Лесная дорога с надписью «DWAALWEG»."],["Конец","Скелет с косой: «EINDE»."],["Кости","Поле с двумя игральными костями."]]},"merelle":{"title":"Мельница и воздушный змей","artist":"Клодина Стелла по рисунку Жака Стеллы","date":"1657","place":"Франция (Париж)","game":"Мерель (мельница)","medium":"Резцовая гравюра","size":"11,7 × 14,1 см","credit":"","p":["Лист 17 из серии детских игр, гравированный Клодиной Стеллой по рисункам её дяди, художника Жака Стеллы. По словам музея, он из альбома в 51 гравюру. Играют пухлые голые дети — путти.","Слева впереди они играют в мерель (мельницу) на доске, процарапанной на каменной плите. Справа на земле — линии игры франк-дю-карро, где монеты бросают на квадраты, а вдали ребёнок бежит с воздушным змеем. Стихи внизу говорят, что каждый старается играть хорошо."],"spots":[["Доска мельницы","Доска, вырезанная на камне, с фишками."],["Воздушный змей","Змей высоко в небе."],["Ребёнок со змеем","Бежит с бечёвкой."],["Франк-дю-карро","Квадраты и диагонали на земле."],["Указывающий ребёнок","С чем-то в руке показывает на линии."],["Заголовок","«LA MERELLE, & LE CERF VOLANT»."]]},"feldcards":{"title":"Игра в карты за садовым столом (стереофотография)","artist":"Неизвестный автор","date":"1850–1880","place":"Неизвестно (на обороте штамп фирмы из Гронингена)","game":"Карты","medium":"Альбуминовый отпечаток (стереофотография)","size":"8,5 × 17,0 см","credit":"","p":["Стереофотография: семья или компания друзей играет в карты за столом в саду, позади решётка, увитая плющом. На обороте штамп «Feldbrugge & Co., Groningen» (Нидерланды) — вероятно, магазина или издателя, продававшего снимок.","Бородач слева высоко поднял карту, вот-вот хлопнет ею по столу. Мужчина, подпёрший голову рукой, мальчик с картами, седой старик и женщина, глядящая сзади, дополняют мгновение. Поскольку все должны были долго не двигаться, сцена, вероятно, поставлена."],"spots":[["Поднятая карта","Карта в высоко поднятой руке бородача."],["На столе","Уже сыгранные карты."],["Карты мальчика","Карты мальчика, видимого со спины."],["Старик","Седой мужчина справа."],["Смотрящая женщина","Стоит позади и следит за игрой."],["Вышитый стул","Стул впереди с цветастой обивкой."]]},"tempel":{"title":"Игровое поле «Храм счастья»","artist":"Неизвестный автор","date":"1816","place":"Нидерланды","game":"Гонка с костями","medium":"Ксилография с наборным текстом","size":"43,0 × 48,5 см","credit":"","p":["Игровой лист с полями от 1 до 74, закрученными спиралью. В центре — круглый храм у моря; лист с правилами из того же собрания называет его «Храмом счастья» и описывает игру бросков, то есть в кости.","Большинство полей — пустые кружки, но кое-где есть розы, шипы, кости, кованые ворота, паром и другое, а также слова «LEER GELD» (плата за учёбу), «DOMHEID» (глупость) и «WYSHEID» (мудрость). Вероятно, это нравоучительная гонка через добрые и дурные поступки к храму."],"spots":[["Храм счастья","Храм у моря в центре: поле 74, финиш."],["Поле 1","Старт слева внизу."],["Плата за учёбу","Поле с надписью «LEER GELD»."],["Кости","Две кости в верхнем ряду."],["Паром","Картинка «OVER HAAL» (переправа) в нижнем ряду."],["Глупость и мудрость","Слова «DOMHEID» и «WYSHEID» справа."]]},"verkeer":{"title":"Миниатюрная доска для веркера","artist":"Неизвестный автор","date":"1690–1710","place":"Нидерланды (Амстердам)","game":"Веркер (родственник нард), шахматы, мельница","medium":"Орех с инкрустацией оливой, чёрным деревом, самшитом и костью; медная фурнитура","size":"В сложенном виде 5,8 × 5,8 см (в раскрытом 11,6 см)","credit":"","p":["Игровая доска шириной едва шесть сантиметров, открывающаяся как шкатулка. Снаружи — шахматная доска и поле для мельницы, внутри — доска для веркера, нидерландского родственника нард. Закрывается на медные петли и крошечный крючок.","Внутри сохранились кость, девять шашек из кости, четыре из чёрного дерева и три монетки. Судя по музейному номеру, она, вероятно, из обстановки кукольного дома Петронеллы Оортман. Несмотря на размер, инкрустация тщательная и устроена как у настоящей доски."],"spots":[["Игральная кость","Кость не больше рисового зёрнышка."],["Костяные шашки","Круглые белые шашки из кости."],["Шашки из чёрного дерева","Чёрные шашки."],["Клинья","Треугольники из светлого и тёмного дерева."],["Петли","Медные петли для складывания."],["Крючок","Крошечный медный крючок-застёжка."]]},"silverbd":{"title":"Миниатюрная серебряная доска с шашками","artist":"Фредерик ван Странт II","date":"1739","place":"Нидерланды (Амстердам)","game":"Шашки, мельница","medium":"Серебро","size":"5,4 × 5,4 см","credit":"","p":["Серебряная доска стороной всего 5,4 сантиметра: 64 поля, приподнятый бортик и кольцо для подвешивания. Тёмные поля покрыты тонкой гравированной штриховкой, а на обороте выгравированы линии для мельницы.","На ней клеймо Амстердама, датная буква E (1739) и клеймо серебряника Фредерика ван Странта II. Вместе с ней сохранились пятнадцать шашек: восемь с цветком и семь с кругом. Вероятно, это серебряная миниатюра для кукольного дома или витрины."],"spots":[["Шашки с цветком","Шашки с выбитым цветком."],["Шашки с кругом","Шашки, отмеченные кругом."],["Кольцо","Кольцо на углу доски."],["Гравированные поля","Тёмные поля с тонкой штриховкой."],["Гладкие поля","Светлые, гладко отполированные поля."],["Бортик","Приподнятый край вокруг доски."]]},"schaak1550":{"title":"Шахматы с конными фигурами","artist":"Неизвестный автор","date":"1550","place":"Германия","game":"Шахматы","medium":"Самшит и хвойная древесина","size":"Самая высокая фигура 10,5 см","credit":"","p":["Каждая фигура стоит на точёном постаменте с оградкой из флеронов, на нём вырезаны всадники и кони. Короли и королевы едут на конях или мулах, будто на охоту.","По записи музея, чёрный король сидит на вздыбленном коне, попирающем дракона, а на шее у него цепь, напоминающая орден Золотого руна, — возможно, это Карл V. Королева едет боком на муле с соколом на руке. Справа — шуточная фигура: обезьяна верхом на человеке."],"spots":[["Король","Коронованный бородатый король верхом."],["Королева","Королева боком на муле, с соколом."],["Обезьяна","Обезьяна на спине человека."],["Шуточная фигура","Слева — человек верхом на другом."],["Существа под копытами","Драконы и звери под копытами."],["Постаменты","Точёные постаменты с флеронами."]]},"kraaij":{"title":"Мужчины и женщины играют в настольную игру в гостиной","artist":"Неизвестный автор","date":"1900–1910","place":"Вероятно, Нидерланды","game":"Нарды (бэкгеммон)","medium":"Коллодионный отпечаток с прямым почернением","size":"8,0 × 11,1 см","credit":"","p":["Лист из семейного альбома, где есть и снимки виноторговцев «Kraaij & Co., Бордо — Амстердам». В гостиной с люстрой мужчины и женщины, вероятно родные и друзья, сидят за столом.","На столе раскрыта доска-шкатулка, а женщины по обе стороны держат по стаканчику для костей. В записи музея сказано «настольная игра», но по шкатулке и стаканчикам это, вероятно, нарды. Рядом кофейные чашки, позади клетка с птицей — тихий домашний вечер."],"spots":[["Доска-шкатулка","Раскрытая складная шкатулка-доска."],["Левый стаканчик","Стаканчик женщины в очках."],["Правый стаканчик","Женщина в платье в горошек собирается бросить."],["Птичья клетка","Клетка на подставке позади."],["Люстра","Лампы со стеклянными плафонами под потолком."],["Стоящий мужчина","Справа, смотрит на игру."]]},"braekel":{"title":"Старик и старуха играют в шашки","artist":"Фердинанд де Бракелер (старший)","date":"1862","place":"Бельгия (Антверпен)","game":"Шашки","medium":"Офорт","size":"21,8 × 16,5 см","credit":"","p":["Офорт антверпенского художника де Бракелера (1792–1883) с подписью слева внизу «Ferdinand De Braekeleer Antwerpen 1862». В старой кухне с очагом старик и старуха сидят за маленьким столом.","На доске круглые шашки; он берёт одну, а она разводит руками, будто возражает. На полу лежит шляпа, туда же упало несколько шашек. На полке тарелки, в окне видны дома."],"spots":[["Доска и шашки","Доска с круглыми шашками на столе."],["Старик","Склонился и берёт шашку."],["Старуха","В чепце, говорит и жестикулирует."],["Шляпа на полу","Шляпа старика на полу."],["Подпись","«Ferdinand De Braekeleer Antwerpen 1862»."],["Тарелки","Большие тарелки на полке над очагом."]]},"billiard":{"title":"Бильярд","artist":"По рисунку Г. У. Банбери (гравёр неизвестен)","date":"1780","place":"Англия (Лондон)","game":"Бильярд","medium":"Офорт и пунктир","size":"30,0 × 39,1 см","credit":"","p":["Гравюра по рисунку английского карикатуриста Генри Уильяма Банбери, изданная в Лондоне в 1780 году фирмой Watson & Dickinson. По словам музея, это четвёртый лист серии.","Двое мужчин играют в бильярд, остальные смотрят, затаив дыхание. Один склонился над столом для удара, другой держит кий на плече. На стене стойка для киёв и два круглых счётных циферблата. Музей отмечает, что стол кажется треугольным."],"spots":[["Стол и шары","Стол с сукном и шары на нём."],["Целящийся","Склонился над столом для удара."],["Мужчина с кием","Ждёт с длинным кием."],["Счётные циферблаты","Два круга на стене, вероятно, для счёта очков."],["Стойка для киёв","Ряд киёв у стены."],["Двое смеющихся","Двое зрителей справа смеются вместе."]]},"baizi":{"title":"Сто детей (фрагмент)","artist":"Сюй Янхун","date":"XVIII век","place":"Китай","game":"Вэйци (го)","medium":"Горизонтальный свиток; тушь (и лёгкая подцветка) на бумаге","size":"29,8 × 526 см (весь свиток)","credit":"","p":["Сцена игры в го, вырезанная из свитка длиной больше пяти метров китайского профессионального художника Сюй Янхуна. В саду сто детей играют, музицируют, читают и пишут. «Сто детей» — важная тема азиатского искусства, символ многодетности и процветания семьи.","Свиток известен и по поздней копии японского мастера Тани Бунтё, которая хранится в том же музее. Возле банановых листьев и «учёного камня» дети окружили доску для го на низкой подставке; двое играют с чашами камней в руках, остальные заглядывают."],"spots":[["Доска","Доска для го на низкой подставке, с камнями."],["Ребёнок, делающий ход","В синей куртке, рука в чаше с камнями."],["Второй игрок","В белом, склонился над доской."],["Руки за головой","Ребёнок смотрит сзади."],["«Учёный камень»","Большой камень, весь в отверстиях."],["Веер из перьев","Ребёнок слева с веером из перьев."]]},"schenkcards":{"title":"Две китаянки играют в карты","artist":"Питер Схенк (младший)","date":"1727–1775","place":"Нидерланды (тема — Китай)","game":"Карты","medium":"Офорт","size":"16,5 × 26,2 см","credit":"","p":["Лист из первой части альбома «Новоизобретённые китайцы» с фигурами и пейзажами в китайском духе, изданного амстердамским гравёром и издателем Питером Схенком младшим. Это шинуазри — модное в Европе представление о воображаемом Китае.","Согласно записи музея, две китаянки играют в карты в саду, а справа подходит женщина с полным подносом. Карты на столе похожи на европейские. Слева на подставке отдыхает кролик, по реке плывёт парусник."],"spots":[["Карты","Карты на столе; они похожи на европейские."],["Женщина слева","С картами в руке смотрит на партнёршу."],["Женщина справа","Кладёт карту на стол."],["Женщина с подносом","Несёт поднос с едой."],["Кролик","Отдыхает на подставке слева."],["Парусник","Лодка на реке."]]},"gosaucer":{"title":"Блюдце с игроками в го","artist":"Неизвестный автор","date":"1725–1735","place":"Китай","game":"Го (вэйци)","medium":"Фарфор, надглазурные эмали, золочение","size":"Диаметр 16,4 см","credit":"","p":["Китайское блюдце, расписанное мягкими надглазурными красками «розового семейства». На донце — знак: кисть, скипетр жуи и брусок туши в двойном круге. В записях музея фигуры описаны то как мужчина и женщина, играющие в го, то как три женщины, две из которых играют.","В комнате на столе лежит доска для го; двое друг против друга ставят камни, третий стоит позади и смотрит. На столе жёлтые чаши для камней, позади — подставка с вазой цветов, справа — большой синий сосуд."],"spots":[["Доска","Доска для го с камнями на столе."],["Игрок слева","В бледно-лиловом, облокотился на стол."],["Игрок справа","В розовом, ставит камень."],["Зритель","Стоит позади."],["Ваза","Ваза с цветами на подставке."],["Синий сосуд","Большой сосуд справа."]]},"cheetham":{"title":"Маленькая карточная компания (в России)","artist":"Неизвестный автор","date":"1903–1904","place":"Россия","game":"Карты","medium":"Желатиновый серебряный отпечаток с прямым почернением","size":"9,2 × 11,5 см","credit":"","p":["Из альбома английской семьи Читэм, жившей в России; на паспарту по-английски написано «a little card-party». Музей отмечает, что это, вероятно, английские друзья, навестившие Джозефа Читэма.","В комнате с обоями трое сидят за столом с цветастой скатертью, раскрыв карты веером. На столе два подсвечника, а женщина посередине смеётся, раскрывая карты. Вероятно, это непринуждённая минута с земляками в далёкой стране."],"spots":[["Карты левого мужчины","Карты бородача."],["Карты женщины","Женщина посередине раскрыла карты веером."],["Мужчина справа","Подался вперёд, с картами."],["Подсвечники","Два подсвечника на столе."],["Скатерть","Большая скатерть с цветами и узором."],["Надпись","«a little card-party» на паспарту."]]},"problem":{"title":"Задача (стереофотография)","artist":"Неизвестный автор","date":"1852–1863","place":"Неизвестно","game":"Шахматы","medium":"Стереофотография, раскрашенная","size":"8,4 × 17,4 см","credit":"","p":["Английское название — «The Problem» («Задача»). Двое в белых париках и костюмах в духе XVIII века играют в шахматы за резным столиком — раскрашенная пара стереоснимков. На обороте от руки написано «Simons».","Младший обхватил щёки обеими руками и уставился на доску, а пожилой напротив ухмыляется. Вероятно, это поставленная театральная сцена, где сразу видно, у кого «задача». У их ног лежит собака."],"spots":[["Доска и фигуры","Доска и фигуры на резном столике."],["Задумавшийся","Обхватил голову руками и смотрит на доску."],["Ухмыляющийся","Пожилой мужчина в синем кафтане улыбается."],["Собака","Собака лежит у ног."],["Красная занавесь","Раскрашенная занавесь позади."],["Второй снимок","Правый вид; в стереоскопе обретает глубину."]]},"tarocco":{"title":"Десять карт из колоды таро","artist":"Неизвестный автор (вероятно, по Джузеппе Марии Мителли)","date":"1660–1718","place":"Италия (Болонья)","game":"Тарокки (карточные игры с козырями)","medium":"Офорт и резцовая гравюра, частично раскрашенные светло-коричневым","size":"Десять карт на паспарту","credit":"","p":["Десять карт из болонской колоды таро, наклеенные рядом на лист. Таро сначала служило не для гадания, а для карточных игр с козырями. Слева вверху — титульная карта; музей предполагает, что на портрете может быть художник Мителли.","В верхнем ряду четыре фигуры, среди них коронованный мужчина и всадник; в нижнем — от шестёрки до десятки масти монет, на каждой столько монет, каков её номер. Отпечатанные линии частично подкрашены светло-коричневым."],"spots":[["Титульная карта","Слева вверху: портрет в рамке и надпись."],["Коронованный мужчина","Фигура в короне со скипетром."],["Стоящая женщина","Женщина в короне с кубком."],["Всадник","Карта с фигурой на коне."],["Десятка монет","Слева внизу: десять монет."],["Шестёрка монет","Справа внизу: шесть монет."]]},"kindtegel":{"title":"Изразцы с играющими детьми","artist":"Неизвестный автор","date":"1680–1730","place":"Нидерланды","game":"Детские игры (ходули, качели и др.)","medium":"Фаянс (дельфтские изразцы), роспись синим","size":"107 × 80 см (48 изразцов)","credit":"","p":["Поле из сорока восьми изразцов — восемь в высоту и шесть в ширину. На каждом синим нарисованы двое играющих детей, а в углах — маленький орнамент, который называют «паучком».","Один ребёнок ходит на ходулях, другого раскачивают на качелях, третьи присели над чем-то на земле: на каждом изразце своя игра. Такие изразцы с «детскими играми» любили в Нидерландах; ими, вероятно, облицовывали стены кухонь и пространство вокруг каминов."],"spots":[["Ходули","Ребёнок на ходулях."],["Качели","Ребёнка раскачивают на качелях."],["Игра на земле","Дети присели и играют с чем-то на земле."],["Паучки","Маленькие орнаменты в углах."],["Сорок восемь изразцов","Восемь рядов по шесть изразцов."],["Последний изразец","Изразец в правом нижнем углу."]]},"dammolen":{"title":"Миниатюрная доска для шашек и мельницы","artist":"Неизвестный автор","date":"1740–1760","place":"Нидерланды (Амстердам)","game":"Шашки, мельница","medium":"Орех со светлой заполняющей пастой","size":"4,2 × 4,0 × 1,5 см","credit":"","p":["Крошечная ореховая доска шириной около четырёх сантиметров. Почти квадратная, с бортиком, с одной стороны она служит шашечной доской, с другой — полем для мельницы.","На шашечной стороне клетки вырезаны и заполнены светлой пастой, образуя шахматный узор на дереве; на стороне мельницы прорезанные линии заполнены той же пастой. Столь маленькая, она, вероятно, предназначалась для кукольного дома."],"spots":[["Заполненные клетки","Вырезанные клетки со светлой пастой."],["Деревянные клетки","Клетки из открытого ореха."],["Бортик","Приподнятый край вокруг."],["Ближний угол","Ближайший к нам угол."],["Толщина","Боковая сторона высотой 1,5 см."],["Дальний ряд","Самый дальний ряд клеток."]]},"karelpiece":{"title":"Шашка с портретом Карла Великого (половина)","artist":"Неизвестный автор","date":"1525–1575","place":"Германия (Нюрнберг)","game":"Шашки или трик-трак","medium":"Самшит","size":"Диаметр 5,3 см","credit":"","p":["Одна сторона шашки, вырезанной из самшита. В центре — профиль в лавровом венке, по кругу надпись «CAROLVS. MAGNVS. IMPER. AVGVST.» (Карл Великий, император).","В музее хранится больше десятка таких шашек, на каждой — император или императрица от Древнего Рима до Средневековья: Тиберий, Агриппина, Людовик Благочестивый, Оттон и другие. Вероятно, это роскошный набор, задуманный как галерея правителей."],"spots":[["Профиль","Профиль Карла в лавровом венке."],["Венок","Лавровое кольцо вокруг портрета."],["CAROLVS","Слова «CAROLVS. MAGNVS» вверху."],["AVGVST","Слова «IMPER. AVGVST» слева."],["Звёздочка","Маленькая звезда-разделитель."],["Край","Ступенчатый край шашки."]]},"vdberge":{"title":"Голландская игра — славная жизнь! (Карты)","artist":"Питер ван ден Берге (замысел и издание)","date":"1694–1737","place":"Нидерланды (Амстердам)","game":"Карты","medium":"Офорт, печать à la poupée красным, синим и зелёным","size":"27,3 × 17,0 см","credit":"","p":["Сатира амстердамского гравёра и издателя ван ден Берге под названием «LE JEU HOLLANDOIS. LA BELLE VIE!». По словам музея, в трактире мужчины играют в карты, а черти возле вздыхающего мужчины с поднятым бокалом и под столом выигрывают его деньги.","В нидерландских стихах внизу беспечный кутила сетует, что собачьи и петушиные бои, карты и кости растопили его деньги. По сторонам два чёрта по-немецки зовут его веселиться за костями и картами. На картине на задней стене тоже собачьи и петушиные бои."],"spots":[["Мужчина с бокалом","Кутила в большом парике поднимает бокал."],["Карты в руке","Веер карт в его руке."],["Чёрт слева","Ухмыляющийся чёрт позади него."],["Чёрт под столом","Сгребает рассыпанные монеты."],["Картина с боями","Картина с собачьими и петушиными боями."],["Заголовок и стихи","«LE JEU HOLLANDOIS» и жалоба кутилы."]]},"crespi":{"title":"Дети играют в кости","artist":"Джузеппе Мария Креспи","date":"1675–1747","place":"Италия","game":"Кости","medium":"Офорт","size":"22,5 × 15,1 см","credit":"","p":["Авторский офорт болонского художника Креспи. По словам музея, четверо детей играют в кости на улице, а внизу добавлены три строки итальянских стихов.","Присевший ребёнок только что бросил кости на землю, трое смотрят. Стихи говорят о костях и числах, короткой игре и тающих деньгах — вероятно, это предостережение от азарта даже в детской забаве."],"spots":[["Кости","Маленькие кости на земле."],["Присевший ребёнок","Только что бросил кости."],["Стоящий ребёнок","Смотрит на бросок."],["Ребёнок справа","Сидит на земле и наблюдает."],["Ребёнок позади","Выглядывает из-за других."],["Стихи","Три строки итальянских стихов."]]},"epinal":{"title":"Большая игра в гусёк (Эпиналь)","artist":"Pellerin & Cie (Эпиналь)","date":"1791–1900","place":"Франция (Эпиналь)","game":"Гусёк (гонка на костях)","medium":"Ксилография, раскрашенная жёлтым, красным, зелёным и синим; наборный текст","size":"39,8 × 59,0 см","credit":"","p":["Цветной лист печатни Пеллерена в Эпинале на востоке Франции с французским заголовком «GRAND JEU DE L’OIE». По словам музея, на спирали из 63 полей изображены гуси, другие животные и люди, а в центре напечатаны нидерландское название «GANZENBORD!» и правила.","По правилам бросают две кости; попав на гуся, ходят ещё столько же. Мост (6) ведёт на 12, трактир (19) — пропуск двух ходов, у колодца (31) ждут, пока придёт другой, лабиринт (42) отправляет на 30, а смерть (58) — в начало. Побеждает тот, кто попадёт ровно на 63. По бокам — фишки для вырезания."],"spots":[["63: гусь","Цель, поле 63: гусь на пруду."],["Правила","Нидерландские правила в центре."],["Фишки для вырезания","Круглые нумерованные фишки по бокам."],["Заголовок","«GRAND JEU DE L’OIE» вверху."],["Играющие дети","Дети в левом нижнем углу."],["Издатель","«PELLERIN & Cie» слева вверху."]]},"matham":{"title":"Пара за триктраком","artist":"Якоб Матам (издатель), стихи Симона Совия","date":"1621","place":"Нидерланды (Харлем)","game":"Триктрак (родственник нард)","medium":"Резцовая гравюра","size":"17,9 × 20,0 см","credit":"","p":["Третий лист серии из четырёх, изданной харлемским гравёром и издателем Матамом. По словам музея, нарядная пара играет в триктрак на деньги за маленьким столом; на столе кошелёк, дама держит кости.","Длинные клинья доски и светлые и тёмные шашки чётко выгравированы. Внизу латинские и нидерландские стихи; нидерландские предупреждают, что не только излишество в вине будит нечистые мысли, но и игра в кости идёт против всякой выгоды. Позади мальчик поднимает бокал вина."],"spots":[["Доска","Доска для триктрака с клиньями и шашками."],["Мужчина делает ход","Мужчина в шляпе тянется к доске."],["Дама с костями","В большом воротнике, держит кости."],["Мальчик с бокалом","Поднимает бокал вина позади."],["Кошелёк","Кошелёк со ставками на столе."],["Стихи","Предостерегающие строки на латыни и нидерландском."]]},"jardin":{"title":"Трое мужчин играют в карты за садовым столом, с наблюдателем (Франция)","artist":"Неизвестный автор (французский фотограф-любитель)","date":"1900–1910","place":"Франция","game":"Карты","medium":"Альбуминовый отпечаток","size":"11,8 × 17,2 см","credit":"","p":["Из альбома французского фотографа-любителя, где есть также снимки семьи, винокурни «Delizy & Doistau», армии и достопримечательностей Франции.","В тени сада, посыпанного гравием, трое мужчин играют в карты за маленьким столиком, а пожилой человек с белой бородой стоит позади и смотрит. На столе карты, мужчина в канотье разглядывает свои. Вероятно, это непринуждённая минута в кругу семьи или друзей."],"spots":[["Карты на столе","Сыгранные карты."],["Наблюдатель","Пожилой мужчина с белой бородой стоит позади."],["Мужчина в канотье","Посередине, разглядывает карты."],["Мужчина справа","В тёмном сюртуке, с картами."],["Мужчина слева","В светлом пиджаке."],["Сад","Гравий и кусты сада."]]},"lamplight":{"title":"Люди играют в карты (под лампой)","artist":"Неизвестный автор","date":"1900–1910","place":"Неизвестно","game":"Карты","medium":"Желатиновый серебряный отпечаток","size":"7,5 × 10,0 см","credit":"","p":["Небольшая фотография из альбома, в музее названная «Люди, играющие в карты». Ни фотограф, ни место неизвестны.","При свете керосиновой лампы под потолком женщина в полосатом платье, девочка и мальчики сидят за столом со скатертью с бахромой и держат карты веером. Снимать в тёмной комнате было трудно; вероятно, хотели запечатлеть семейный вечер."],"spots":[["Скатерть с бахромой","Узорчатая скатерть с бахромой."],["Лампа","Керосиновая лампа под потолком."],["Женщина в полоску","Сидит в белом полосатом платье."],["Карты женщины","Карты, которые она держит веером."],["Карты девочки","Девочка посередине раскрыла карты."],["Мальчик справа","Подался вперёд, с картами."]]},"borduur":{"title":"Вышитая крышка ломберного стола с игроками в карты","artist":"Неизвестный автор","date":"1700–1725","place":"Неизвестно","game":"Карты","medium":"Вышивка крупным и мелким крестом шерстью и шёлком","size":"100 × 185 см","credit":"","p":["Вышивка с крышки складного ломберного стола, выполненная разноцветной шерстью и шёлком крупным (гро-пуэн) и мелким (пти-пуэн) стежком. Внутри фигуры со срезанными углами идёт рамка из волют и цветов.","В пейзаже в центре две дамы и кавалер играют в карты за столом. По записи музея, на столе лежат кошелёк, карты и другие игровые принадлежности. Стол для карт, к месту украшенный карточной игрой."],"spots":[["Стол","Зелёный стол с кошельком и картами."],["Кавалер","Мужчина в шляпе слева."],["Дама в центре","Дама за столом."],["Дама справа","Дама в синем."],["Деревья","Деревья за фигурами."],["Рамка","Рамка из волют и цветов."]]},"piquet":{"title":"Ткань с напечатанной игрой в пикет","artist":"Неизвестный автор","date":"1725–1750","place":"Неизвестно","game":"Пикет (карточная игра)","medium":"Лён, набойка красным и фиолетовым","size":"73,0 × 82,5 см","credit":"","p":["Льняное покрывало для карточного стола, сплошь покрытое красной и фиолетовой набойкой с принадлежностями карточной игры. В записи музея оно описано и как носовой платок.","По кайме и в центре рассыпаны карты для пикета — игры в 32 карты от семёрки до туза; посередине — кошелёк, вокруг — фишки. Фигуры парижского рисунка, с именами Цезарь, Аржина, Ожье и другими."],"spots":[["Кошелёк","Кошелёк со ставками в центре."],["Фигуры","Короли и дамы парижского рисунка."],["Фишки","Круглые фишки."],["Кайма из карт","Полоса карт вокруг ткани."],["Колоды рубашкой вверх","Колоды с видимой рубашкой."],["Запечатанная пачка","Запечатанная пачка карт справа внизу."]]},"schaakglas":{"title":"Бокал с гравировкой: двое за шахматами","artist":"Неизвестный автор","date":"1815–1830","place":"Неизвестно","game":"Шахматы","medium":"Бесцветное прозрачное стекло, гравировка колесом","size":"Высота 13,7 см","credit":"","p":["Прозрачный бокал на ножке; рисунок и надпись вырезаны маленьким вращающимся колесом. За столиком с двумя свечами двое мужчин сидят друг против друга у шахматной доски.","Левый в очках курит трубку, правый склонился над доской, на столе стоит бокал вина. Вокруг идёт французская надпись: знать ходы — дело простое; знать игру — плод гения."],"spots":[["Доска","Доска с фигурами."],["Мужчина с трубкой","Слева, в очках и с трубкой."],["Склонившийся","Справа, разглядывает доску."],["Свечи","Две свечи за доской."],["Бокал вина","Бокал на столе."],["Надпись","Слова, выгравированные по-французски."]]},"arlequin":{"title":"Лото Арлекина","artist":"Неизвестный автор (издание Миндерманн и Ко)","date":"1818–1845","place":"Нидерланды (Амстердам)","game":"Лото / игра-гонка","medium":"Гравюра, раскрашенная от руки, наклеенная на картон","size":"Неизвестно","credit":"","p":["Игровой лист, где полем служит сам Арлекин, стоящий широко расставив ноги. Квадратные поля с номерами от 1 до 32 идут по его зелёному костюму и между ног. Внизу — заголовок «Arlequin’s Lotto-Spel» и имя амстердамского издателя Миндерманн и Ко.","Лицо его закрыто сетчатой маской, в руках шляпа и что-то вроде деревянного меча. Некоторые поля помечены «HW» или «P». Раскрашенную гравюру наклеили на картон, вероятно, чтобы использовать как игровое поле."],"spots":[["Сетчатая маска","Сетка, закрывающая лицо."],["Поле 1","Старт под левой ногой."],["Поле HW","Поле с пометкой «HW»."],["P 32","Поле 32 с буквой «P»."],["Заголовок","«Arlequin’s Lotto-Spel» внизу."],["Шляпа","Шляпа в правой руке."]]},"vicaire":{"title":"Партия викария","artist":"Рене Гайян (по подписи на листе)","date":"1888–1893","place":"Франция","game":"Карты","medium":"Фототипия (по данным музея)","size":"10,4 × 15,6 см","credit":"","p":["Иллюстрация из «Бюллетеня Парижского фотоклуба» под названием «La partie du Vicaire» («Партия викария»). На поле напечатано «Phototype René Gayant» и «Héliogravure Lemercier»: снимок, вероятно, Гайяна, печать — Лемерсье. В книге лист был вплетён боком.","На кухне с развешанными кастрюлями и сковородами священник в чёрной сутане сидит за столом и разглядывает карты, у мужчины напротив тоже карты в руках. Мужчина в кепке подпёр подбородок, а молодой человек, прижав руку к уху, следит за игрой. Живописный свет и композиция под стать клубу, посвящённому художественной фотографии."],"spots":[["Карты викария","Карты, которые разглядывает священник."],["Викарий","В чёрной сутане с белым воротничком."],["Мужчина с картами","Кудрявый, смотрит в карты."],["Молодой зритель","Рукой у щеки следит за игрой."],["Мужчина в кепке","Подпёр подбородок рукой."],["Стена кухни","Кастрюли и половники на стене."]]},"israels":{"title":"Шахматисты","artist":"Исаак Израэльс","date":"1875–1922","place":"Нидерланды","game":"Шахматы","medium":"Пастель","size":"40,0 × 57,5 см","credit":"","p":["Пастель нидерландского художника Исаака Израэльса (1865–1934), известного быстрыми живыми сценами городской жизни Амстердама. В комнате со светлым окном мужчины сидят вокруг шахматной доски.","Двое впереди подпёрли щёку или подбородок и не сводят глаз с доски, а мужчина в кепке склонился позади. Фигуры не прорисованы, а положены цветными мазками; кажется, идёт долгое раздумье."],"spots":[["Доска и фигуры","Доска; фигуры — цветные мазки."],["Левый игрок","Подпёр щёку, смотрит на доску."],["Правый игрок","Подпёр подбородок, думает."],["Мужчина в кепке","Склонился сзади."],["Окно","Светлое окно слева."],["Стул","Стул справа."]]},"louisxi":{"title":"Людовик XI и его дочь Анна де Божё","artist":"Адриан Йозеф Верховен-Балл","date":"1866","place":"Бельгия (Антверпен)","game":"Шахматы","medium":"Гравюра (вероятно, офорт)","size":"26,4 × 31,3 см","credit":"","p":["Антверпенский художник Верховен-Балл сам нарисовал и выгравировал этот лист («pinx et sculp» внизу). Музейное название — «Людовик XI и его дочь Анна де Божё играют в шахматы». Строка внизу упоминает вторую выставку Ассоциации антверпенских художников.","Людовик XI, король Франции XV века, сидит у стола в меховой мантии, а его дочь Анна, подперев подбородок, изучает доску. На столе фигуры и ваза с фруктами, на полу лежит собака, позади стоит вооружённый страж. Вероятно, это воображаемая сцена с историческими отцом и дочерью."],"spots":[["Доска и фигуры","Шахматная доска и фигуры на столе."],["Людовик XI","Король в шляпе и меховой мантии."],["Анна","Дочь, подперев подбородок."],["Спящая собака","Поджарая собака на полу."],["Страж","Вооружённый воин в тени."],["Заголовок","«LOUIS XI ET SA FILLE ANNE DE BEAU-JEU»."]]},"bruining":{"title":"Монахи играют в шашки","artist":"Тилеман Като Брёйнинг","date":"1750–1850","place":"Нидерланды","game":"Шашки","medium":"Офорт","size":"20,6 × 16,8 см","credit":"","p":["Офорт нидерландского гравёра Брёйнинга с надписью слева внизу «T. Bruining inv. et fecit aqua fort» (придумал и выполнил офортом). По словам музея, двое монахов играют в шашки за столом.","Позади стоят третий монах и чёрт в монашеской рясе. У стола стоит Смерть, тоже переодетая монахом, пряча косу за спиной. Монахи так увлечены игрой, что не замечают непрошеных гостей."],"spots":[["Шашечная доска","Доска и шашки на столе."],["Смерть","В рясе, прячет косу за спиной."],["Двое позади","Третий монах и чёрт в рясе."],["Левый игрок","Монах, склонившийся над доской."],["Правый игрок","Задумчивый монах, руки на столе."],["Подпись","«T. Bruining inv. et fecit aqua fort»."]]},"vanvliet":{"title":"Игроки в триктрак при свече","artist":"Ян Гиллис ван Флит","date":"1631–1634","place":"Нидерланды (Лейден)","game":"Триктрак (родственник нард)","medium":"Офорт и резцовая гравюра","size":"15,2 × 13,4 см","credit":"","p":["Лист ван Флита, работавшего в Лейдене рядом с Рембрандтом. По словам музея, в тёмной комнате с кроватью под балдахином слева двое играют в триктрак, а справа стоят мужчина и женщина.","Мужчина в чёрном, спиной к нам, низко склонился над доской, а соперник смеётся, положив руку на её край. Клинья и шашки видны отчётливо. Источника света не видно, но освещены лишь доска и лица — вероятно, ночная партия."],"spots":[["Доска","Доска для триктрака с клиньями и шашками."],["Смеющийся игрок","Смеётся, рука на краю доски."],["Склонившийся","В чёрном, спиной к нам, над доской."],["Мужчина в шляпе","Стоит позади в широкополой шляпе."],["Фигура в воротнике","Справа, подняв руку."],["Полог кровати","Занавеси кровати под балдахином слева."]]},"hermans":{"title":"Две женщины и девочка у шахматной доски","artist":"Франсуа Херманс (ателье)","date":"1857–1895","place":"Нидерланды (Роттердам)","game":"Шахматы","medium":"Альбуминовый отпечаток (карт-де-визит)","size":"10,1 × 6,2 см","credit":"","p":["Фотография формата «карт-де-визит» из семейного альбома, на обороте напечатано название ателье: «François Hermans / Hang 421 / Rotterdam». Вероятно, это семейный памятный портрет, снятый в ателье.","На маленьком круглом столике стоит шахматная доска; женщина слева коснулась фигуры, а женщина справа задумчиво подпёрла щёку. Между ними стоит девочка и смотрит прямо на нас. Все трое, должно быть, замерли на время долгой выдержки."],"spots":[["Шахматная доска","Доска и фигуры на круглом столике."],["Рука, делающая ход","Женщина слева касается фигуры."],["Девочка","Стоит за доской и смотрит на нас."],["Задумчивая женщина","Женщина справа, рука у щеки."],["Скамеечка","Круглая скамеечка для ног на полу."],["Окно","Решётчатое окно справа в глубине."]]},"norimberg":{"title":"Шашка с видом Нюрнберга","artist":"Неизвестный автор","date":"1690","place":"Германия (Нюрнберг)","game":"Шашки или трик-трак","medium":"Самшит","size":"Диаметр 5,4 см, толщина 1,5 см","credit":"","p":["Самшитовая шашка с рельефным видом Нюрнберга, его башен и замка. Сверху надпись «SVB AQVILAE ROMANAE ALIS QVIESCO» («покоюсь под крылами римского орла»), снизу — «NORIBERGA VRBIVM REGINA» («Нюрнберг, царица городов»).","По записи музея, на другой стороне — портреты императора Иосифа I и семи курфюрстов. Вероятно, это гордость имперского города Нюрнберга, вырезанная на игровой фишке."],"spots":[["Вид города","Нюрнберг со шпилями и стенами."],["Верхний девиз","«SVB AQVILAE ROMANAE…»."],["Нижний девиз","«NORIBERGA VRBIVM REGINA»."],["Эмблема","Маленький знак вверху."],["Замок","Замок на возвышенности справа."],["Край","Ступенчатый край шашки."]]},"toovenaar":{"title":"«Волшебник»: новая весёлая детская игра","artist":"Неизвестный автор","date":"1856","place":"Нидерланды (Амстердам)","game":"Игра-гонка (родственница «Гусёка»)","medium":"Литография с наборным текстом, раскрашенная от руки","size":"44,5 × 53,5 см","credit":"","p":["Игра-гонка под названием «DE TOOVENAAR» («Волшебник»), «новая весёлая детская игра», с полями от 1 до 63 по спирали. В центре — волшебник у стола с черепом, чашей, луной и звёздами, за ним дьявольские существа; по углам — черти со звериными головами.","Правила в центре почти как в «Гусёке». Бросают две кости: шесть и три с первого броска ведут на 26, пять и четыре — на 53. Волшебник даёт ход повторить, как гусь; мост стоит одну ставку, трактир — две и пропуск хода, лабиринт на 42 отправляет на три назад, а Смерть заставляет платить и начинать сначала."],"spots":[["Волшебник","Волшебник у своего стола в центре."],["Заголовок и правила","Заголовок «DE TOOVENAAR» и правила."],["Финиш 63","Последнее поле спирали."],["Угловые черти","Черти со звериными головами."],["Внешний круг","Поля с картинками по краю."],["Стол","Череп и чаша на столе."]]},"fichesdoos":{"title":"Костяная шкатулка с фишками","artist":"Мариаваль-младший","date":"1725","place":"Франция (Париж)","game":"Фишки для карточных игр","medium":"Слоновая кость","size":"2 × 8 × 6 см","credit":"","p":["Шкатулка из слоновой кости размером с ладонь для фишек, заменявших деньги в карточных играх. На крышке — коронованная женщина со скипетром на облаках рядом с павлином и два герба; с павлином это, вероятно, богиня Юнона.","По записи музея, на крышке надпись «Mariaval le Jeune a Rouen fecit», а снизу — орёл и птицы, одна из них на виселице. Внутри сохранились девятнадцать больших и шесть маленьких фишек с насекомыми и цветами."],"spots":[["Коронованная женщина","Женщина в короне на облаках."],["Павлин","Павлин у её ног."],["Гербы","Два герба справа вверху."],["Птичка","Птица на жёрдочке рядом с ней."],["Облака","Облака, на которых она сидит."],["Край крышки","Край и застёжка крышки."]]},"vuilmere":{"title":"Мать художника за шашками","artist":"Эдуар Вюйар","date":"Ок. 1890–91","place":"Франция","game":"Шашки","medium":"Пастель с графитом, растушёвкой и стиранием на веленевой бумаге цвета слоновой кости","size":"37,5 × 30,5 см","credit":"","p":["Пастель французского художника Вюйара, изображающая его мать. Вюйар жил с ней и снова и снова рисовал сцены в её доме, где она работала портнихой. Справа внизу подпись «E Vuillard».","Две фигуры в чёрном сидят за ярко-оранжевым столом; передняя держит шашечную доску. Согласно музейному названию, здесь изображена мать художника. Внутри чёрного овала люди и мебель растворяются в массах цвета и формы."],"spots":[["Доска","Доска в чёрно-белую клетку."],["Дальняя фигура","Фигура в чёрном по ту сторону стола."],["Ближняя фигура","Та, что держит доску."],["Оранжевый стол","Яркое пятно цвета."],["Узорчатая стена","Узор из вьющихся линий."],["Подпись","«E Vuillard» справа внизу."]]},"dewitte":{"title":"Двое мужчин играют в шахматы","artist":"Адриан де Витте","date":"1877","place":"Бельгия","game":"Шахматы","medium":"Вероятно, офорт","size":"13,2 × 12,5 см","credit":"","p":["Небольшой лист бельгийского художника и гравёра де Витте (1850–1935) из Льежа. По словам музея, в литературе (Клерк, 1981) предполагается, что шахматисты — Терм и Зейен.","За столом со скатертью молодой человек, скрестив руки, смотрит на доску, а пожилой напротив задумчиво подпёр голову рукой. За доской видно что-то вроде ящика для фигур. В тёмной комнате, переданной тонкой штриховкой, идёт тихая партия."],"spots":[["Доска и фигуры","Доска и фигуры на столе."],["Ящик","Похоже, ящик за доской."],["Молодой человек","Скрестив руки, смотрит на доску."],["Пожилой мужчина","Подпёр голову, думает."],["Скатерть","Ткань на столе."],["Стул","Спинка гнутого стула слева."]]},"orphans":{"title":"Сироты (дети играют в шашки)","artist":"Чарльз Роллс по рисунку У. Гилла","date":"1810–1834","place":"Англия","game":"Шашки","medium":"Гравюра (резцовая)","size":"22,6 × 13,9 см","credit":"","p":["Гравюра с подписью внизу «THE ORPHANS» (Сироты) и надписью «Painted by W. Gill, Engraved by C. Rolls». По словам музея, она, возможно, использовалась в The Keepsake — подарочном альманахе, выходившем в Лондоне.","На кухне девочка и мальчик играют в шашки на доске, положенной на бочку. Позади женщина вышивает, а в глубине стоит то, что музей называет ткацким станком. Название позволяет думать, что это сироты, которых приютила эта женщина."],"spots":[["Шашечная доска","Доска и шашки на бочке."],["Девочка","Склонилась к доске."],["Мальчик","Передвигает шашку."],["Вышивающая женщина","Вышивает позади них."],["Кувшин","Кувшин на полу."],["Заголовок","«THE ORPHANS» внизу."]]},"richelieu":{"title":"Людовик XIII и Ришельё","artist":"Ян Фредерик Кристиан Реклебен","date":"1850","place":"Нидерланды (Амстердам)","game":"Шахматы","medium":"Гравюра на стали","size":"24,2 × 29,6 см","credit":"","p":["Гравюра на стали амстердамского гравёра Реклебена с заголовком «1850. NEDERLANDSCH MUSEUM. Pl. II.». По словам музея, она, возможно, иллюстрировала статью в журнале «Нидерландский музей».","Перед большим камином король Франции Людовик XIII и его министр кардинал Ришельё играют в шахматы, а вокруг собрались мужчины. Кардинал, сидящий слева, тянется к фигуре; король в шляпе с перьями непринуждённо откинулся. Слева у края стоит монах, скрестив руки."],"spots":[["Шахматная доска","Доска и фигуры на покрытом столе."],["Ришельё","Кардинал тянется к фигуре."],["Людовик XIII","Король в шляпе с перьями."],["Монах","Скрестив руки, смотрит слева."],["Придворные","Мужчины, собравшиеся справа."],["Заголовок","«LODEWIJK DE XIII EN RICHELIEU» внизу."]]},"coster":{"title":"Мужчины играют в триктрак при свече (по Де Костеру)","artist":"По картине Адама де Костера (гравёр Ворстерман)","date":"1619–1628","place":"Фландрия","game":"Триктрак (родственник нард)","medium":"Резцовая гравюра","size":"37,1 × 35,1 см","credit":"","p":["Гравюра по картине фламандского мастера ночных сцен при свечах Адама де Костера, с надписями внизу «A. De Coster pi.» и «Vorsterman». По словам музея, двое мужчин стоя играют у стола в триктрак при свече.","Слева смотрит мужчина с трубкой; справа девушка играет на лютне, а мужчина в шапке указывает на свечу. Игрок на переднем плане, спиной к нам, склонился над столом, его соперник держит руку над доской. Одна свеча освещает сцену, выхватывая лишь лица и руки."],"spots":[["Доска","Доска на столе, наполовину в тени."],["Свеча","Единственная свеча, освещающая сцену."],["Игрок со спины","Склонился над столом."],["Соперник","Держит руку над доской."],["Курильщик","Смотрит слева с трубкой во рту."],["Лютнистка","Девушка с лютней справа."]]},"kiebitz":{"title":"Кибиц (зритель за картами)","artist":"Ханс Вацек","date":"1894","place":"Вероятно, Австрия","game":"Карты","medium":"Автотипия (книжная иллюстрация)","size":"10,0 × 12,1 см","credit":"","p":["Фотография венского художественного фотографа Ханса Вацека с подписью «HANS WATZEK 94» справа вверху. Она напечатана автотипией в книге, колонтитул которой спрашивает: «Фотография — искусство?»","Немецкое слово «Kiebitz» — это птица чибис, а в просторечии — зритель, который вмешивается в карточную игру. Мужчина в шляпе разглядывает карты, а тот, что впереди с длинной трубкой, заглядывает сбоку. Зернистый, живописный тон типичен для художественной фотографии той поры, стремившейся к живописи."],"spots":[["Карты","Карты, которые разглядывает правый мужчина."],["Игрок","В котелке, с трубкой во рту."],["Зритель","Мужчина с длинной трубкой — вероятно, «кибиц» из названия."],["Пивная кружка","Стеклянная кружка на столе."],["Подпись автора","«HANS WATZEK 94» справа вверху."],["Подпись под снимком","«HANS WATZEK. — KIEBITZ.» внизу."]]},"evdvelde":{"title":"Игроки в триктрак в саду замка","artist":"Эсайас ван де Велде","date":"1630","place":"Нидерланды","game":"Триктрак (родственник нард)","medium":"Чёрный мел и серая размывка","size":"18,5 × 30,1 см","credit":"","p":["Рисунок Эсайаса ван де Велде (1587–1630), одного из зачинателей голландской жанровой и пейзажной живописи, с подписью «E.V.VELDE» справа внизу. По словам музея, нарядное общество играет в триктрак за столом в саду замка.","Склонившийся над доской мужчина и сидящий напротив играют, позади смотрят дамы. Слева впереди — охладитель для вина с двумя кувшинами, дальше — мальчик и павлин у фонтана. Изящный день игры под открытым небом."],"spots":[["Доска","Доска для триктрака на столе."],["Склонившийся мужчина","В шляпе, наклонился к доске."],["Сидящий мужчина","Нога на ногу, у доски."],["Смотрящие дамы","Стоят позади, следят за игрой."],["Павлин и мальчик","Павлин и мальчик у фонтана."],["Охладитель для вина","Сосуд и два кувшина слева впереди."]]},"cooghen":{"title":"Двое мужчин играют в триктрак","artist":"Леендерт ван дер Кохен","date":"1666","place":"Нидерланды (Харлем)","game":"Триктрак (родственник нард)","medium":"Офорт","size":"9,3 × 15,6 см","credit":"","p":["Офорт харлемского художника ван дер Кохена с годом «1666», процарапанным на стене над доской. По словам музея, двое мужчин в трактире играют за столом в триктрак, а женщина заглядывает через плечо левого.","Пожилой мужчина слева в кафтане с меховой опушкой держит высокий бокал; молодой справа — в заметной шляпе с перьями. В окне сидит маленькая обезьянка. Борт и клинья доски прорисованы чётко."],"spots":[["Доска","Доска для триктрака на столе."],["Пожилой мужчина","В кафтане с меховой опушкой."],["Бокал","Высокий бокал в его руке."],["Заглядывающая женщина","Смотрит через плечо левого игрока."],["Обезьянка","Маленькая обезьянка в окне."],["Мужчина в шляпе с перьями","Молодой игрок в шляпе с перьями."]]},"roybet":{"title":"Шахматист","artist":"Фердинан Руабе","date":"1875","place":"Франция (Париж)","game":"Шахматы","medium":"Вероятно, офорт","size":"26,1 × 19,6 см","credit":"","p":["Лист, нарисованный и выгравированный французским художником Руабе, любившим изображать кавалеров XVII века («F. Roybet del. et sc.» слева внизу). Ниже — название «LE JOUEUR D’ÉCHECS», справа — имя издателя Кадара.","Мужчина в шляпе с перьями, со шпагой на боку, сидит боком на скамье и тянется к фигурам. Соперника не видно; кажется, он в одиночку обдумывает позицию. На полке позади — кружка, кувшин и бокалы."],"spots":[["Доска и фигуры","Доска и фигуры на скамье."],["Кавалер","Мужчина в шляпе с перьями."],["Протянутая рука","Рука тянется к фигуре."],["Шпага","Длинная шпага на боку."],["Посуда на полке","Кружка, кувшин и бокалы."],["Название","«LE JOUEUR D’ÉCHECS»."]]},"capot":{"title":"«Святой Пётр, друг мой, вы капот!» (художник и натурщик за картами)","artist":"Неизвестный автор (издание Aubert & Cie)","date":"1838","place":"Франция (Париж)","game":"Карты (вероятно, пикет)","medium":"Литография","size":"30,5 × 22,2 см","credit":"","p":["Литография из парижской сатирической газеты «Шаривари» от 9 сентября 1838 года, лист 13 серии «Les Artistes». Подпись: «St. Pierre, mon ami, vous êtes capot!»","По словам музея, художник называет партнёра по картам «святым Петром», потому что тот позирует для святого на картине. «Капот» в пикете — проигрыш всех взяток, так что игра, вероятно, пикет."],"spots":[["Карты на столе","Сыгранные карты на столике."],["Натурщик","Длинноволосый, сидит спиной; волосы и борода как у святого на картине — вероятно, натурщик."],["Художник","Мужчина справа с картами, вероятно, художник."],["Картина со святым","Недописанный святой на мольберте."],["Табурет","Деревянный табурет натурщика."],["Подпись","«St. Pierre, mon ami, vous êtes capot!»"]]}};
